/* LUME V0.2 — reorganização das telas e ações explícitas. */
const originalAction=action, originalSubmit=submit, originalProjectPage=projectPage;
function actions(edit,del,extra=''){return `<div class="record-actions">${extra}${btn('Editar',edit,'edit')}${btn('Excluir',del,'trash','danger')}</div>`}
workCard=function(p){let done=p.checks.filter(x=>x.done).length;return `<article class="card job-card">${p.cover?'<img class="project-cover-small" src="'+p.cover+'" alt="Capa do trabalho">':''}<div class="between"><span class="service-icon">${icon(p.type==='Vídeo'?'video':'camera')}</span>${badge(p.stage)}</div><h3>${esc(p.name)}</h3><p class="muted">${esc(client(p.clientId)?.name)}</p><div class="job-dates"><span>Data <b>${fmt(p.date)}</b></span><span>Entrega <b>${fmt(p.due)}</b></span></div><div class="job-footer"><small>${done}/${p.checks.length} tarefas concluídas</small>${btn('Abrir trabalho','project:'+p.id,'arrow','primary')}</div>${actions('edit:project:'+p.id,'delete-job:'+p.id)}</article>`};
homePage=function(){const activeJobs=state.projects.filter(active),next=state.events.filter(e=>e.end>=today()).sort((a,b)=>a.start.localeCompare(b.start)),todo=activeJobs.flatMap(p=>p.checks.filter(c=>!c.done).map(c=>({p,c}))).slice(0,4);return header('Início','O que você precisa fazer hoje.')+`<div class="quick-actions">${[['Novo cliente','new:client','users'],['Nova proposta','new:quote','file'],['Novo trabalho','new:project','folder'],['Agendar / lembrar','new:event','calendar']].map(([t,a,i])=>`<button data-action="${a}" class="quick-action">${icon(i)}<span>${t}</span>${icon('plus')}</button>`).join('')}</div><div class="summary-strip"><button data-action="nav:projects"><b>${activeJobs.length}</b> trabalhos ativos</button><button data-action="nav:quotes"><b>${(state.quotes||[]).filter(q=>q.status==='Rascunho'||q.status==='Enviada').length}</b> propostas em aberto</button><button data-action="nav:finance"><b>${money(activeJobs.reduce((n,p)=>n+Math.max(0,p.value-totals(p.id).paid),0))}</b> a receber</button></div><div class="grid cols2 section"><section class="card"><div class="between section-title"><h2>Próximos compromissos</h2>${btn('Agenda','nav:agenda','calendar')}</div>${next.slice(0,4).map(eventRow).join('')||empty('Agenda livre','Adicione uma sessão, atividade ou lembrete.','new:event','Agendar')}</section><section class="card"><div class="between section-title"><h2>Tarefas pendentes</h2><span class="badge">Por trabalho</span></div>${todo.map(({p,c})=>`<div class="task-row"><input type="checkbox" data-check="${p.id}:${c.id}" aria-label="Concluir ${esc(c.text)}"><div class="grow"><b>${esc(c.text)}</b><small>${esc(p.name)}</small></div><button class="icon-btn" data-action="project-tasks:${p.id}" aria-label="Abrir tarefas">${icon('arrow')}</button></div>`).join('')||empty('Sem tarefas pendentes','As tarefas dos trabalhos aparecem aqui.')}</section></div><section class="section"><div class="between section-title"><h2>Trabalhos em andamento</h2><button class="link-btn" data-action="nav:projects">Ver todos →</button></div><div class="grid cols3">${activeJobs.slice(0,3).map(workCard).join('')||`<div class="card full">${empty('Comece por um cliente','Depois crie a proposta ou o trabalho.','new:client','Cadastrar cliente')}</div>`}</div></section>`};
eventRow=function(e){return `<article class="event-record"><div class="row"><div class="date-tile"><strong>${e.start.slice(8,10)}</strong><small>${new Date(e.start).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</small></div><div class="grow"><b>${esc(e.title)}</b><small class="block">${fmt(e.start.slice(0,10))} · ${e.start.slice(11)} – ${e.end.slice(11)}</small><small class="block">${esc(e.type)}${e.location?' · '+esc(e.location):''}</small></div></div>${actions('event:'+e.id,'delete:event:'+e.id)}</article>`};
checkRows=function(p){return p.checks.map(c=>`<div class="task-record"><label class="check-row ${c.done?'done':''}"><input type="checkbox" data-check="${p.id}:${c.id}" ${c.done?'checked':''}><span>${esc(c.text)}</span></label>${actions('edit-check:'+p.id+':'+c.id,'remove-check:'+p.id+':'+c.id)}</div>`).join('')||empty('Nenhuma tarefa','Ex.: carregar baterias, revisar roteiro ou editar as fotos.','check:'+p.id,'Criar tarefa')};
function quoteForm(id=null,pid=null){if(!state.clients.length){toast('Cadastre um cliente antes da proposta.');return openForm('client')}const q=(state.quotes||[]).find(q=>q.id===id)||{},p=project(pid||q.projectId);modal(id?'Editar proposta':'Nova proposta',`<input type="hidden" name="id" value="${id||''}"><div class="grid cols2 form-cols">${field('Título da proposta','title',q.title||p?.name||'','text','required maxlength="160"')}${select('Cliente','clientId',state.clients.map(c=>[c.id,c.name]),q.clientId||p?.clientId,'required')}${select('Vincular a trabalho (opcional)','projectId',[['','Sem vínculo'],...state.projects.map(p=>[p.id,p.name])],q.projectId||pid||'')}${select('Situação','status',['Rascunho','Enviada','Aceita','Recusada'],q.status||'Rascunho')}${field('Valor da proposta (R$)','amount',((q.amount??p?.value??0)/100).toFixed(2),'number','min="0" step="0.01" required')}${field('Válida até','validUntil',q.validUntil||addDays(15),'date','required')}${area('Serviços, entregáveis e condições','scope',q.scope||p?.brief||'','required')}</div><p class="legend">A situação é registrada por você. Não envia mensagens nem confirma pagamentos automaticamente.</p>`,'quote',id?'Salvar alterações':'Criar proposta')}
function quotesPage(){const qs=(state.quotes||[]).filter(q=>(q.title+' '+client(q.clientId)?.name).toLowerCase().includes(query.toLowerCase()));return header('Propostas e contratos','Documentos personalizados com o logo do fotógrafo.',btn('Nova proposta','new:quote','plus','primary'))+documentTabs('quotes')+`<div class="toolbar"><div class="search">${icon('search')}<input id="search" aria-label="Buscar proposta" value="${esc(query)}" placeholder="Buscar proposta ou cliente"></div></div><div class="grid cols3">${qs.map(q=>`<article class="card quote-card"><div class="between"><span class="service-icon">${icon('file')}</span>${badge(q.status)}</div><h3>${esc(q.title)}</h3><p class="muted">${esc(client(q.clientId)?.name)}</p><strong class="quote-value">${money(q.amount)}</strong><p class="legend">Validade: ${fmt(q.validUntil)}</p>${actions('edit-quote:'+q.id,'delete-quote:'+q.id,btn('Gerar PDF','print-quote:'+q.id,'file'))}</article>`).join('')||`<div class="card full">${empty('Nenhuma proposta','Crie um orçamento com valor, escopo e validade.','new:quote','Criar proposta')}</div>`}</div>`}
projectPage=function(){const p=project(selected);if(!p)return empty('Trabalho não encontrado','Abra a lista de trabalhos.','nav:projects','Ver trabalhos');const c=client(p.clientId),t=totals(p.id),tabs=['Dados','Orientações','Agenda','Tarefas','Entregas','Valores'];if(!tabs.includes(tab))tab='Dados';let content='';
if(tab==='Dados')content=`<div class="grid cols2"><section class="card"><div class="between section-title"><h2>Dados do trabalho</h2>${btn('Editar','edit:project:'+p.id,'edit')}</div><div class="data-list"><div><small>Cliente</small><b>${esc(c.name)}</b></div><div><small>Serviço</small><b>${esc(p.type)}</b></div><div><small>Local</small><b>${esc(p.location||'Não informado')}</b></div><div class="grid cols2"><div><small>Data principal</small><b>${fmt(p.date)}</b></div><div><small>Prazo geral</small><b>${fmt(p.due)}</b></div></div><div><small>Observações</small><p class="note">${esc(p.notes||'Nenhuma observação.')}</p></div></div>${waButton(c,p)}</section><section class="card"><h2>O que você quer fazer?</h2><div class="action-list">${btn('Agendar sessão ou lembrete','project-event:'+p.id,'calendar')}${btn('Adicionar tarefa','check:'+p.id,'check')}${btn('Criar proposta','new-project-quote:'+p.id,'file')}${btn('Registrar recebimento ou despesa','project-transaction:'+p.id,'wallet')}${btn('Abrir Modo Sessão','session:'+p.id,'camera')}</div></section></div>`;
if(tab==='Orientações')content=`<section class="card"><div class="between section-title"><h2>Como será o trabalho</h2>${actions('brief:'+p.id,'clear-brief:'+p.id)}</div><p class="note">${esc(p.brief||'Descreva o que o cliente espera, o estilo, o roteiro e os detalhes importantes.')}</p></section>`;
if(tab==='Agenda')content=`<section class="card"><div class="between section-title"><h2>Compromissos deste trabalho</h2>${btn('Adicionar','project-event:'+p.id,'plus','primary')}</div>${state.events.filter(e=>e.projectId===p.id).sort((a,b)=>a.start.localeCompare(b.start)).map(eventRow).join('')||empty('Nenhum compromisso','Agende sessões, atividades e lembretes.','project-event:'+p.id,'Adicionar')}</section>`;
if(tab==='Tarefas')content=`<section class="card"><div class="between section-title"><h2>O que precisa ser feito</h2>${btn('Nova tarefa','check:'+p.id,'plus','primary')}</div>${checkRows(p)}</section>`;
if(tab==='Entregas')content=`<section class="card"><div class="between section-title"><h2>O que será entregue ao cliente</h2>${btn('Nova entrega','delivery:'+p.id,'plus','primary')}</div>${p.deliveries.map(d=>`<article class="delivery-record"><div class="between"><div><h3>${esc(d.name)}</h3><small>Prazo: ${fmt(d.due)}</small></div>${badge(d.status)}</div>${d.url?`<p><a href="${esc(d.url)}" target="_blank" rel="noopener">Abrir arquivo / galeria ↗</a></p>`:''}${actions('delivery:'+p.id+':'+d.id,'remove-delivery:'+p.id+':'+d.id)}</article>`).join('')||empty('Nenhuma entrega','Ex.: 30 fotos, filme de 5 minutos ou álbum.','delivery:'+p.id,'Adicionar entrega')}</section><p class="legend">Situação registrada manualmente. Os links abrem serviços externos.</p>`;
if(tab==='Valores')content=`<div class="grid cols3">${metric('Valor combinado',money(p.value),'Valor cadastrado no trabalho','file')}${metric('Recebido líquido',money(t.paid),'Recebimentos menos estornos','wallet')}${metric('Falta receber',money(Math.max(0,p.value-t.paid)),'Não representa lucro','clock')}</div><section class="card section"><div class="between section-title"><h2>Recebimentos e despesas</h2>${btn('Lançar valor','project-transaction:'+p.id,'plus','primary')}</div>${financeRows(p.id)}</section>`;
return `<button class="link-btn row" data-action="nav:projects">${icon('back')} Todos os trabalhos</button>${p.cover?'<img class="project-cover-header" src="'+p.cover+'" alt="Capa do trabalho">':''}<div class="job-heading"><div><small>${esc(c.name)} · ${esc(p.type)}</small><h1>${esc(p.name)}</h1></div><label>Etapa<select id="stage">${stages.map(s=>`<option ${s===p.stage?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="tabs job-tabs">${tabs.map(x=>`<button class="tab ${x===tab?'active':''}" data-action="tab:${x}">${x}</button>`).join('')}</div>${content}<div class="work-management">${btn('Editar trabalho','edit:project:'+p.id,'edit')}${btn('Duplicar','duplicate:'+p.id,'copy')}${btn('Arquivar','archive:'+p.id,'folder')}${btn('Excluir trabalho','delete-job:'+p.id,'trash','danger')}</div>`};
gearPage=function(){return header('Equipamentos','Cadastre seu kit e acompanhe a situação de cada item.',btn('Novo equipamento','new:gear','plus','primary'))+`<div class="equipment-grid">${state.gear.map(g=>`<article class="card"><div class="between"><span class="service-icon">${icon('camera')}</span>${badge(g.status)}</div><h3>${esc(g.name)}</h3><p class="muted">${esc(g.model||g.category)}</p><p class="note">${esc(g.notes||'Sem observações.')}</p>${actions('gear:'+g.id,'delete:gear:'+g.id)}</article>`).join('')||`<div class="card full">${empty('Nenhum equipamento','Adicione câmeras, lentes e acessórios.','new:gear')}</div>`}</div>`};
clientsPage=function(){const cs=state.clients.filter(c=>(c.name+' '+c.email).toLowerCase().includes(query.toLowerCase()));return header('Clientes','Seus contatos e os trabalhos de cada um.',btn('Novo cliente','new:client','plus','primary'))+`<div class="toolbar"><div class="search">${icon('search')}<input id="search" placeholder="Buscar cliente" aria-label="Buscar cliente" value="${esc(query)}"></div></div><div class="grid cols3">${cs.map(c=>`<article class="card"><div class="row"><div class="avatar">${esc(initials(c.name))}</div><div><h3 style="margin:0 0 5px">${esc(c.name)}</h3><small>${esc(c.type)}</small></div></div><p class="note section">${esc(c.phone||c.email||'Sem contato informado')}</p><p class="legend">${state.projects.filter(p=>p.clientId===c.id).length} trabalhos vinculados</p>${actions('edit:client:'+c.id,'delete:client:'+c.id,btn('Ver cliente','client:'+c.id,'arrow'))}</article>`).join('')||`<div class="card full">${empty('Cadastre seu primeiro cliente','O cliente pode ter várias propostas e trabalhos.','new:client')}</div>`}</div>`};
financeRows=function(pid){const ts=state.transactions.filter(t=>!pid||t.projectId===pid).sort((a,b)=>b.date.localeCompare(a.date));return ts.map(t=>`<article class="money-record"><div class="between"><div><h3>${esc(t.description)}</h3><small>${fmt(t.date)} · ${esc(t.type)}</small><small class="block">${esc(project(t.projectId)?.name)}</small></div><strong class="amount ${t.type==='Recebimento'?'positive':'negative'}">${t.type==='Recebimento'?'+':'−'} ${money(t.amount)}</strong></div>${actions('transaction:'+t.id,'delete:transaction:'+t.id)}</article>`).join('')||empty('Nenhum lançamento','Registre recebimentos e despesas efetivados.')};
morePage=function(){return header('Mais opções','Acesse as outras áreas do estúdio.')+`<div class="more-grid">${[['quotes','Propostas e contratos','Criar, editar e gerar PDF em A4','file'],['finance','Financeiro','Recebimentos, despesas e saldo','wallet'],['gear','Equipamentos','Cadastro e situação do seu kit','camera'],['settings','Configurações','Perfil, senha e backup','settings']].map(([r,t,d,i])=>`<button class="card more-card" data-action="nav:${r}">${icon(i)}<span class="grow"><b>${t}</b><small class="block">${d}</small></span>${icon('arrow')}</button>`).join('')}</div>`};
function printSavedQuote(id){const q=state.quotes.find(q=>q.id===id),c=client(q.clientId);const w=window.open('','_blank');if(!w)return toast('Permita abrir a janela para imprimir.');w.document.write(`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Proposta · ${esc(q.title)}</title><style>body{font:16px/1.7 Arial;max-width:760px;margin:35px auto;padding:25px;color:#202728}header{border-bottom:3px solid #c99564}pre{white-space:pre-wrap;font:inherit}.price{font-size:28px;font-weight:bold}button{padding:14px}@media print{button{display:none}}</style><header><p>${esc(state.profile.name)}</p><h1>Proposta de serviço</h1></header><h2>${esc(q.title)}</h2><p>Cliente: ${esc(c.name)}<br>Validade: ${fmt(q.validUntil)}<br>Situação registrada: ${esc(q.status)}</p><h3>Escopo e condições</h3><pre>${esc(q.scope)}</pre><p class="price">${money(q.amount)}</p><small>Documento gerado em ${fmt(today())}. A situação foi registrada pelo profissional; este arquivo não comprova assinatura ou pagamento.</small><p><button onclick="window.print()">Imprimir / salvar PDF</button></p></html>`);w.document.close()}
action=async function(a){const [cmd,id,arg]=a.split(':');if(a==='new:quote')return quoteForm();if(cmd==='edit-quote')return quoteForm(id);if(cmd==='new-project-quote')return quoteForm(null,id);if(cmd==='print-quote')return printSavedQuote(id);if(cmd==='delete-quote'){if(!confirm('Excluir esta proposta? O trabalho e seus pagamentos serão mantidos.'))return;await commit(d=>d.quotes=d.quotes.filter(q=>q.id!==id),'Proposta excluída');toast('Proposta excluída.');return}if(cmd==='project-tasks'){go('project',id);tab='Tarefas';render();return}if(cmd==='clear-brief'){if(!confirm('Excluir as orientações deste trabalho?'))return;await commit(d=>d.projects.find(p=>p.id===id).brief='','Orientações excluídas');return}if(cmd==='edit-check'){const c=project(id).checks.find(c=>c.id===arg);modal('Editar tarefa',`<input type="hidden" name="pid" value="${id}"><input type="hidden" name="cid" value="${arg}">${field('Descrição da tarefa','text',c.text,'text','required maxlength="240"')}`,'edit-check');return}
if(cmd==='delete-job'){const p=project(id),events=state.events.filter(e=>e.projectId===id).length,tx=state.transactions.filter(t=>t.projectId===id).length,qs=(state.quotes||[]).filter(q=>q.projectId===id).length;modal('Excluir trabalho',`<p>Você vai excluir <b>${esc(p.name)}</b>.</p><div class="notice">Também serão excluídos: ${events} compromissos, ${p.checks.length} tarefas, ${p.deliveries.length} entregas e ${tx} lançamentos financeiros. Os totais serão recalculados. Os vínculos e custos de parceiros deste trabalho também serão excluídos.</div><p class="note">O cliente e ${qs} proposta(s) serão mantidos. As propostas perderão apenas o vínculo com este trabalho.</p><input type="hidden" name="pid" value="${id}">${field('Digite EXCLUIR para confirmar','confirmation','','text','required autocomplete="off"')}`,'delete-job','Excluir definitivamente');return}
if(cmd==='delete'&&id==='client'&&(state.quotes||[]).some(q=>q.clientId===arg))throw Error('Este cliente possui propostas. Exclua ou altere o cliente dessas propostas antes de excluí-lo.');return originalAction(a)};
submit=async function(kind,f){const v=Object.fromEntries([...new FormData(f)].filter(([k])=>!['coverFile','logoFile'].includes(k)));if(kind==='quote'){if(!v.title.trim()||!v.scope.trim())throw Error('Preencha o título e o escopo.');if(v.projectId&&project(v.projectId).clientId!==v.clientId)throw Error('O trabalho selecionado pertence a outro cliente.');const q={id:v.id||uid(),title:v.title.trim(),clientId:v.clientId,projectId:v.projectId,status:v.status,amount:cents(v.amount),validUntil:v.validUntil,scope:v.scope.trim()};await commit(d=>{d.quotes??=[];const i=d.quotes.findIndex(x=>x.id===q.id);i<0?d.quotes.push(q):d.quotes.splice(i,1,q)},'Proposta salva');closeModal(true);go('quotes');toast('Proposta salva.');return}if(kind==='edit-check'){if(!v.text.trim())throw Error('Descreva a tarefa.');await commit(d=>d.projects.find(p=>p.id===v.pid).checks.find(c=>c.id===v.cid).text=v.text.trim(),'Tarefa editada');closeModal(true);toast('Tarefa atualizada.');return}if(kind==='delete-job'){if(v.confirmation!=='EXCLUIR')throw Error('Digite EXCLUIR para confirmar.');await commit(d=>{d.projects=d.projects.filter(p=>p.id!==v.pid);d.events=d.events.filter(e=>e.projectId!==v.pid);d.transactions=d.transactions.filter(t=>t.projectId!==v.pid);for(const q of d.quotes||[])if(q.projectId===v.pid)q.projectId=''},'Trabalho e vínculos excluídos');closeModal(true);go('projects');toast('Trabalho excluído e totais atualizados.');return}return originalSubmit(kind,f)};

function documentTabs(which){return `<div class="tabs job-tabs"><button class="tab ${which==='quotes'?'active':''}" data-action="nav:quotes">Propostas</button><button class="tab ${which==='contracts'?'active':''}" data-action="nav:contracts">Contratos</button></div>`}
function contractsPage(){return header('Propostas e contratos','Documentos personalizados com o logo do fotógrafo.',btn('Novo contrato','new-contract','plus','primary'))+documentTabs('contracts')+`<div class="grid cols3">${(state.contracts||[]).map(c=>`<article class="card"><span class="service-icon">${icon('file')}</span><h3 class="section">${esc(c.title)}</h3><p class="muted">${esc(client(c.clientId)?.name)}</p>${actions('edit-contract:'+c.id,'delete-contract:'+c.id,btn('Gerar PDF','pdf-contract:'+c.id,'file'))}</article>`).join('')||`<div class="card full">${empty('Nenhum contrato','Cadastre o texto do contrato e gere o PDF com seu logo.','new-contract','Criar contrato')}</div>`}</div>`}
function contractForm(id){if(!state.clients.length){toast('Cadastre um cliente primeiro.');return openForm('client')}const c=(state.contracts||[]).find(x=>x.id===id)||{};modal(id?'Editar contrato':'Novo contrato',`<input type="hidden" name="id" value="${id||''}"><div class="grid cols2 form-cols">${field('Título','title',c.title||'Contrato de prestação de serviços','text','required maxlength="160"')}${select('Cliente','clientId',state.clients.map(c=>[c.id,c.name]),c.clientId,'required')}${area('Texto do contrato','text',c.text||'','required rows="12"')}</div><p class="legend">Insira seu texto revisado. O PDF não aplica assinatura eletrônica nem certificação.</p>`,'contract')}
function documentHTML(kind,item){const pro=state.profile,c=client(item.clientId);return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${kind==='quote'?'Proposta':'Contrato'} - ${esc(item.title)}</title><style>@page{size:A4 portrait;margin:18mm 16mm 20mm}*{box-sizing:border-box}body{font:11pt/1.55 Arial,sans-serif;color:#202728;margin:0;background:white}.sheet{width:100%;max-width:178mm;margin:auto}header{border-bottom:2px solid #b07a4d;padding-bottom:6mm;margin-bottom:8mm;display:flex;gap:7mm;align-items:center;break-inside:avoid}.logo{max-width:45mm;max-height:23mm;object-fit:contain}.studio{font-size:17pt;font-weight:bold}.contact{font-size:9pt;color:#515b58;overflow-wrap:anywhere}h1{font-size:20pt;line-height:1.25;margin:0 0 7mm;overflow-wrap:anywhere}h2{font-size:12pt;margin:7mm 0 3mm;break-after:avoid}.meta{padding:5mm;background:#f5f2ed;margin-bottom:7mm;break-inside:avoid}.paragraph{white-space:pre-wrap;overflow-wrap:anywhere;margin:0 0 4mm;orphans:3;widows:3}.price{font-size:19pt;font-weight:bold;margin:7mm 0;padding:5mm 0;border-top:1px solid #ddd;break-inside:avoid}.signatures{display:flex;gap:14mm;margin-top:20mm;break-inside:avoid}.signatures div{flex:1;border-top:1px solid #777;text-align:center;padding-top:3mm;font-size:9pt}footer{margin-top:10mm;border-top:1px solid #ddd;padding-top:4mm;font-size:8pt;color:#65706b;break-inside:avoid}.print-controls{padding:14px;background:#edf0ed;margin-bottom:20px;font:14px Arial}.print-controls button{padding:12px 18px;cursor:pointer;background:#192422;color:white;border:0;border-radius:6px}.print-controls p{margin:9px 0 0}@media screen{body{padding:24px;background:#e8ebe8}.sheet{background:white;padding:18mm 16mm;max-width:210mm;box-shadow:0 4px 22px #0001}}@media print{.print-controls{display:none}}</style></head><body><div class="print-controls"><button onclick="window.print()">Gerar PDF / imprimir em A4</button><p>Escolha “Salvar como PDF”, papel A4 (210 × 297 mm), escala 100% e desative os cabeçalhos e rodapés do navegador.</p></div><main class="sheet"><header>${pro.logo?`<img class="logo" src="${pro.logo}" alt="Logo do fotógrafo">`:''}<div><div class="studio">${esc(pro.name)}</div><div class="contact">${esc(pro.owner)}<br>${[pro.phone,pro.email,pro.city].filter(Boolean).map(esc).join(' · ')}</div></div></header><h1>${esc(item.title)}</h1><div class="meta"><b>${kind==='quote'?'PROPOSTA DE SERVIÇO':'CONTRATO'}</b><br>Cliente: ${esc(c.name)}${c.email?'<br>E-mail: '+esc(c.email):''}${c.phone?'<br>Telefone: '+esc(c.phone):''}${kind==='quote'?'<br>Validade: '+fmt(item.validUntil):''}</div><h2>${kind==='quote'?'Serviços e condições':'Condições do contrato'}</h2>${(kind==='quote'?item.scope:item.text).split(/\n\s*\n/).map(p=>`<p class="paragraph">${esc(p)}</p>`).join('')}${kind==='quote'?`<div class="price">Valor total: ${money(item.amount)}</div>`:`<div class="signatures"><div>${esc(pro.owner||pro.name)}<br>Profissional</div><div>${esc(c.name)}<br>Cliente</div></div>`}<footer>Gerado em ${fmt(today())} · ${esc(pro.name)}<br>${kind==='quote'?'Proposta gerada pelo profissional. Não comprova aceite ou pagamento.':'Documento sem assinatura eletrônica aplicada.'}</footer></main></body></html>`}
function openPDF(kind,item){const w=window.open('','_blank');if(!w){toast('Permita abrir uma janela para visualizar e salvar o PDF.');return}w.document.write(documentHTML(kind,item));w.document.close()}
printSavedQuote=function(id){openPDF('quote',state.quotes.find(q=>q.id===id))};
async function readImageFile(file,logo=false){if(!file||!file.size)return '';if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use imagem PNG, JPG ou WebP.');if(file.size>12*1024*1024)throw Error('Escolha uma imagem de até 12 MB.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const max=logo?800:1200,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const result=canvas.toDataURL(logo?'image/png':'image/jpeg',.82);if(result.length>=2800000)throw Error('A imagem ainda está muito grande. Escolha uma versão menor.');return result}finally{URL.revokeObjectURL(url)}}
function hiddenValue(form,name,value){let el=form.querySelector(`[name="${name}"]`);if(!el){el=document.createElement('input');el.type='hidden';el.name=name;form.appendChild(el)}el.value=value}
const uxSubmit=submit,uxAction=action;
submit=async function(kind,f){if(kind==='project'){const file=f.querySelector('[name=coverFile]')?.files?.[0],id=f.querySelector('[name=id]')?.value,remove=f.querySelector('[name=removeCover]')?.checked;hiddenValue(f,'cover',remove?'':file?await readImageFile(file):project(id)?.cover||'')}
if(kind==='profile'){const file=f.querySelector('[name=logoFile]')?.files?.[0],remove=f.querySelector('[name=removeLogo]')?.checked;hiddenValue(f,'logo',remove?'':file?await readImageFile(file,true):state.profile.logo||'')}
if(kind==='contract'){const v=Object.fromEntries(new FormData(f));if(!v.title.trim()||!v.text.trim())throw Error('Preencha título e texto.');const c={id:v.id||uid(),title:v.title.trim(),clientId:v.clientId,text:v.text.trim()};await commit(d=>{d.contracts??=[];const i=d.contracts.findIndex(x=>x.id===c.id);i<0?d.contracts.push(c):d.contracts.splice(i,1,c)},'Contrato salvo');closeModal(true);go('contracts');toast('Contrato salvo.');return}return uxSubmit(kind,f)};
action=async function(a){const [cmd,id,arg]=a.split(':');if(cmd==='new-contract')return contractForm();if(cmd==='edit-contract')return contractForm(id);if(cmd==='pdf-contract')return openPDF('contract',state.contracts.find(c=>c.id===id));if(cmd==='delete-contract'){if(!confirm('Excluir este contrato?'))return;await commit(d=>d.contracts=d.contracts.filter(c=>c.id!==id),'Contrato excluído');return}if(cmd==='delete'&&id==='client'&&(state.contracts||[]).some(c=>c.clientId===arg))throw Error('Este cliente possui contratos. Exclua ou altere o cliente desses contratos antes.');return uxAction(a)};

