gearPage=function(){const html=inventoryPage(),pos=html.indexOf('<div class="equipment-grid">');return html.slice(0,pos)+`<section class="kit-banner"><div><span class="eyebrow">PRONTO PARA O PRÓXIMO CLIQUE</span><h2>Cada peça tem seu papel.</h2><p>Seu kit organizado, da câmera ao último cartão.</p></div></section>`+html.slice(pos)};

