const coverPhotos={people:'assets/cover-people.jpg',desk:'assets/cover-desk.jpg',sunset:'assets/cover-sunset.jpg',capture:'assets/cover-capture.jpg',prints:'assets/cover-prints.jpg',archive:'assets/cover-archive.jpg',portfolio:'assets/cover-portfolio.jpg',time:'assets/cover-time.jpg',gear:'assets/camera-dials.jpg'};
const routeCovers={agenda:'time',projects:'portfolio',clients:'people',finance:'desk',gear:'gear',quotes:'prints',contracts:'archive',settings:'capture',more:'desk',project:'portfolio',session:'sunset'};
function photoCover(key,title,sub='',button=''){return `<section class="page-photo-cover"><img src="${coverPhotos[key]||coverPhotos.portfolio}" alt="" class="cover-${key}"><div class="cover-content"><div><h1>${title}</h1>${sub?'<p>'+sub+'</p>':''}</div>${button}</div></section>`}
