projectPage=function(){const p=project(selected);return (p&&!p.cover?photoCover('portfolio','Seu trabalho','Da ideia à entrega, cada detalhe no lugar.'):'')+coveredProject()};
sessionPage=function(){return photoCover('sunset','Modo sessão','Tudo pronto para registrar o momento.')+coveredSession()};
const baseModal=modal;
modal=function(title,body,submit=null,label='Salvar'){const keys={project:'portfolio',client:'people',event:'time',quote:'prints',contract:'archive',transaction:'desk',gear:'gear',profile:'capture'};const k=keys[submit]||routeCovers[route]||'archive';baseModal(title,`<div class="form-photo-cover"><img src="${coverPhotos[k]}" alt=""></div>`+body,submit,label)};
welcome=function(){return `<div class="welcome reference-access"><div class="welcome-art"><img src="${img.magic}" alt="Câmera envolta em películas e luz dourada"><div class="caption"><h1>Seu olhar cria.<br>Seu estúdio flui.</h1></div></div><div class="welcome-form"><div class="brand"><div class="brand-mark"></div><div><strong>LUME</strong><small>STUDIO</small></div></div><h2>Bem-vindo ao seu estúdio.</h2><p>Organize seus trabalhos, prepare cada sessão e acompanhe suas entregas.</p>${btn('Entrar no meu estúdio','enter:real','arrow','copper')}${btn('Explorar demonstração','enter:demo','','secondary')}<small>Seus registros ficam neste navegador e dispositivo. Faça backups em Configurações. A demonstração usa dados fictícios separados.</small><small>V${VERSION}</small></div></div>`};
// PDF A4 autônomo: páginas JPEG incorporadas, sem janela ou serviço externo.
function pdfFromJpegs(pages){
 const enc=new TextEncoder(),chunks=[],offsets=[0];let size=0;
 const add=x=>{const b=typeof x==='string'?enc.encode(x):x;chunks.push(b);size+=b.length};
 const obj=(n,s)=>{offsets[n]=size;add(n+' 0 obj\n'+s+'\nendobj\n')};
 add('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Count '+pages.length+' /Kids ['+pages.map((_,i)=>(3+i*3)+' 0 R').join(' ')+'] >>');
 pages.forEach((p,i)=>{const n=3+i*3;obj(n,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.276 841.890] /Resources << /XObject << /Im '+(n+1)+' 0 R >> >> /Contents '+(n+2)+' 0 R >>');const bytes=Uint8Array.from(atob(p.split(',')[1]),c=>c.charCodeAt(0));offsets[n+1]=size;add((n+1)+' 0 obj\n<< /Type /XObject /Subtype /Image /Width 1240 /Height 1754 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+bytes.length+' >>\nstream\n');add(bytes);add('\nendstream\nendobj\n');const stream='q 595.276 0 0 841.890 0 0 cm /Im Do Q';obj(n+2,'<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream')});
 const start=size,count=3+pages.length*3;add('xref\n0 '+count+'\n0000000000 65535 f \n');for(let n=1;n<count;n++)add(String(offsets[n]).padStart(10,'0')+' 00000 n \n');add('trailer\n<< /Size '+count+' /Root 1 0 R >>\nstartxref\n'+start+'\n%%EOF');return new Blob(chunks,{type:'application/pdf'});
}
openPDF=async function(kind,item){
 if(!item)throw Error('Salve o documento antes de gerar o PDF.');
 const pro=state.profile,c=client(item.clientId);if(!c)throw Error('Cliente não encontrado.');
 toast('Preparando PDF A4…');
 let logo=null;if(pro.logo){logo=new Image();logo.src=pro.logo;await logo.decode()}
 const pages=[],canvas=document.createElement('canvas');canvas.width=1240;canvas.height=1754;const ctx=canvas.getContext('2d');let y=0,page=0;
 const start=()=>{page++;ctx.fillStyle='#fff';ctx.fillRect(0,0,1240,1754);ctx.fillStyle='#26352d';ctx.font='bold 29px Arial';ctx.fillText(pro.name,94,85);ctx.strokeStyle='#c99564';ctx.beginPath();ctx.moveTo(94,110);ctx.lineTo(1146,110);ctx.stroke();y=150};
 const finish=()=>{ctx.fillStyle='#69716c';ctx.font='18px Arial';ctx.fillText('LUME · '+fmt(today())+' · Página '+page,94,1688);pages.push(canvas.toDataURL('image/jpeg',.94))};
 const line=(t,size=23,bold=false)=>{if(y+size+14>1620){finish();start()}ctx.font=(bold?'bold ':'')+size+'px Arial';ctx.fillStyle='#202a24';ctx.fillText(t,94,y);y+=size+13};
 const text=(value,size=23,bold=false)=>{ctx.font=(bold?'bold ':'')+size+'px Arial';for(const paragraph of String(value||'').split('\n')){let row='';for(const word of paragraph.split(' ')){ctx.font=(bold?'bold ':'')+size+'px Arial';if(row&&ctx.measureText(row+' '+word).width>1052){line(row,size,bold);row=''}if(ctx.measureText(word).width>1052){for(const ch of word){if(ctx.measureText(row+ch).width>1052){line(row,size,bold);row=''}row+=ch}}else row+=(row?' ':'')+word}line(row,size,bold)}};
 start();if(logo){const scale=Math.min(250/logo.width,120/logo.height);ctx.drawImage(logo,94,y,logo.width*scale,logo.height*scale);y+=logo.height*scale+35}
 text(pro.owner,22);text([pro.phone,pro.email,pro.city].filter(Boolean).join(' · '),19);y+=20;text(kind==='quote'?'PROPOSTA DE SERVIÇO':'CONTRATO',20,true);text(item.title,34,true);y+=15;text('Cliente: '+c.name,24,true);if(c.email)text(c.email,20);if(c.phone)text(c.phone,20);if(kind==='quote')text('Validade: '+fmt(item.validUntil),20);y+=28;text(kind==='quote'?'Serviços e condições':'Condições do contrato',25,true);for(const block of (kind==='quote'?item.scope:item.text).split('\n\n')){const heading=/^[A-ZÁÉÍÓÚÃÕÇ /]+$/.test(block)&&block.length<50;text(block,heading?24:23,heading);y+=10}y+=25;
 if(kind==='quote'){text('Valor total: '+money(item.amount),30,true);text('Este documento não comprova aceite ou pagamento.',18)}else{text('________________________________________',22);text(pro.owner||pro.name,20);y+=35;text('________________________________________',22);text(c.name,20);text('Documento sem assinatura eletrônica aplicada.',18)}
 finish();const blob=pdfFromJpegs(pages),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(kind==='quote'?'Proposta-':'Contrato-')+item.title.replace(/[^\p{L}\p{N} -]/gu,'').slice(0,70)+'.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('PDF A4 gerado. Confira os downloads do navegador.');
};
printSavedQuote=function(id){return openPDF('quote',state.quotes.find(q=>q.id===id))};
/* V0.4 — cadastros, parceiros, custos e propostas detalhadas */
const digits=v=>String(v||'').replace(/\D/g,'');
function maskDoc(v){const d=digits(v).slice(0,14);if(d.length<=11)return d.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/(\d{3})\.(\d{3})\.(\d{3})(\d)/,'$1.$2.$3-$4');return d.slice(0,2)+'.'+d.slice(2,5)+'.'+d.slice(5,8)+'/'+d.slice(8,12)+(d.length>12?'-'+d.slice(12):'')}
function maskPhone(v){let d=digits(v).slice(0,13);if(d.length>11&&d.startsWith('55'))d=d.slice(2);d=d.slice(0,11);return d.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{4,5})(\d{4})$/,'$1-$2')}
function parseMoney(v){let s=String(v??'').replace(/R\$/g,'').replace(/\s/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(s))throw Error('Informe o valor em reais, por exemplo 1.250,00.');const n=Number(s);if(!Number.isFinite(n)||n<0||n>1e10)throw Error('Valor fora do limite.');return Math.round(n*100)}
cents=parseMoney;
const rawField=field;
field=function(label,name,value='',type='text',extra=''){if(type==='number'&&(/R\$/.test(label)||['value','amount','rate','discount','extraCost'].includes(name))){const val=value===''?'':money(parseMoney(value));return rawField(label,name,val,'text',extra.replace(/min="[^"]*"|step="[^"]*"/g,'')+' inputmode="decimal" data-mask="money" placeholder="R$ 0,00"')}if(name==='phone')return rawField(label,name,maskPhone(value),'tel',extra+' data-mask="phone" autocomplete="tel"');if(name==='document')return rawField(label,name,maskDoc(value),'text',extra+' inputmode="numeric" data-mask="document"');if(name==='cep')return rawField(label,name,digits(value).replace(/^(\d{5})(\d)/,'$1-'),'text',extra+' inputmode="numeric" maxlength="9" data-mask="cep" autocomplete="postal-code"');return rawField(label,name,value,type,extra)};
function identityFields(x={}){return select('Pessoa física ou jurídica','personType',[['PF','Pessoa física · CPF'],['PJ','Pessoa jurídica · CNPJ']],x.personType||'PF')+field('CPF / CNPJ (opcional)','document',x.document)+field('CEP','cep',x.cep)+field('Rua / avenida','street',x.street)+field('Número','number',x.number)+field('Complemento','complement',x.complement)+field('Bairro','district',x.district)+field('Cidade','city',x.city)+field('UF','uf',x.uf,'text','maxlength="2" placeholder="SP"')}
function validateIdentity(v){const doc=digits(v.document);if(doc&&doc.length!==(v.personType==='PJ'?14:11))throw Error('Confira o CPF (11 dígitos) ou CNPJ (14 dígitos).');if(v.cep&&digits(v.cep).length!==8)throw Error('O CEP deve ter 8 dígitos.');if(v.phone&&![10,11].includes(digits(v.phone).length))throw Error('Informe WhatsApp com DDD e 10 ou 11 dígitos.');if(v.uf&&!/^[A-Za-z]{2}$/.test(v.uf))throw Error('Use duas letras na UF.');}
const v4OpenForm=openForm;
openForm=function(kind,id=null,pid=null){if(kind!=='client')return v4OpenForm(kind,id,pid);const x=client(id)||{};modal(id?'Editar cliente':'Novo cliente',`<input type="hidden" name="id" value="${id||''}"><div class="grid cols2 form-cols"><h3 class="full">Contato</h3>${field('Nome / razão social','name',x.name,'text','required maxlength="120"')}${field('Nome do contato','contact',x.contact)}${field('WhatsApp com DDD','phone',x.phone)}${field('E-mail','email',x.email,'email')}<h3 class="full">Identificação e endereço</h3>${identityFields(x)}${select('Origem','source',['Indicação','Instagram','Site','WhatsApp','Outro'],x.source)}${area('Observações','notes',x.notes)}<input type="hidden" name="type" value="${x.type||'Pessoa'}"></div>`,'client')};
const v4Validate=validate;
validate=function(d){v4Validate(d);d.partners??=[];d.assignments??=[];for(const k of ['partners','assignments']){if(!Array.isArray(d[k])||d[k].length>30000)throw Error('Coleção inválida: '+k);const ids=new Set();for(const x of d[k]){if(!x||!/^[-\w]{1,100}$/.test(x.id)||ids.has(x.id))throw Error('Identificador inválido: '+k);ids.add(x.id)}}for(const p of d.partners)if(typeof p.name!=='string'||!p.name.trim())throw Error('Parceiro sem nome.');const paymentIds=new Set();for(const q of d.quotes)if(q.items){if(!Array.isArray(q.items)||q.items.length>500||quoteAmount(q.items,q.discount||0,q.extraCost||0)!==q.amount)throw Error('Itens ou total da proposta inválidos.')}for(const a of d.assignments){if(!Number.isFinite(a.quantity)||a.quantity<=0||!Number.isSafeInteger(a.rate)||a.rate<0||!Number.isSafeInteger(a.extraCost)||a.extraCost<0||a.amount!==Math.round(a.quantity*a.rate)+a.extraCost||typeof a.service!=='string')throw Error('Detalhamento do custo inválido.');if(a.transactionId){if(paymentIds.has(a.transactionId))throw Error('Pagamento duplicado entre parceiros.');paymentIds.add(a.transactionId)}if(!d.projects.some(p=>p.id===a.projectId)||!d.partners.some(p=>p.id===a.partnerId)||!Number.isSafeInteger(a.amount)||a.amount<0)throw Error('Custo de parceiro inválido.');if(a.transactionId&&!d.transactions.some(t=>t.id===a.transactionId&&t.type==='Despesa'&&t.projectId===a.projectId&&t.amount===a.amount))throw Error('Pagamento do parceiro inválido.')}return d};
function partnerForm(id){const x=(state.partners||[]).find(x=>x.id===id)||{};modal(id?'Editar parceiro':'Novo fornecedor / parceiro',`<input type="hidden" name="id" value="${id||''}"><div class="grid cols2 form-cols">${field('Nome / razão social','name',x.name,'text','required')}${select('Especialidade','category',['Assistente','Segundo fotógrafo','Videomaker','Editor','Maquiagem','Locação','Álbum / impressão','Outro'],x.category)}${field('Contato responsável','contact',x.contact)}${field('WhatsApp com DDD','phone',x.phone)}${field('E-mail','email',x.email,'email')}${identityFields(x)}${area('Observações / condições','notes',x.notes)}</div>`,'partner')}
function partnersPage(){return header('Fornecedores e parceiros','Sua equipe e os serviços que apoiam cada produção.',btn('Novo parceiro','new-partner','plus','primary'))+`<div class="toolbar"><div class="search">${icon('search')}<input id="search" value="${esc(query)}" aria-label="Buscar parceiro" placeholder="Nome ou especialidade"></div></div><div class="grid cols3">${(state.partners||[]).filter(p=>(p.name+' '+p.category).toLowerCase().includes(query.toLowerCase())).map(p=>`<article class="card"><span class="badge">${esc(p.category)}</span><h3 class="section">${esc(p.name)}</h3><p>${esc(p.contact||'')}</p>${waButton(p)}${actions('edit-partner:'+p.id,'delete-partner:'+p.id)}</article>`).join('')||empty('Monte sua rede de apoio','Cadastre profissionais e vincule custos aos trabalhos.','new-partner','Cadastrar parceiro')}</div>`}
function assignmentForm(pid,id){if(!(state.partners||[]).length){toast('Cadastre um parceiro antes de vincular ao trabalho.');return partnerForm()}const x=(state.assignments||[]).find(x=>x.id===id)||{};modal(id?'Editar custo de parceiro':'Adicionar parceiro ao trabalho',`<input type="hidden" name="id" value="${id||''}"><input type="hidden" name="projectId" value="${pid}"><div class="grid cols2 form-cols">${select('Fornecedor / parceiro','partnerId',state.partners.map(p=>[p.id,p.name+' · '+p.category]),x.partnerId,'required')}${field('Serviço ou tarefa','service',x.service,'text','required')}${field('Quantidade (dias, horas ou unidades)','quantity',x.quantity||1,'number','min="0.01" step="0.01" required')}${field('Valor por unidade (R$)','rate',((x.rate||0)/100).toFixed(2),'number','required')}${field('Custos adicionais (R$)','extraCost',((x.extraCost||0)/100).toFixed(2),'number','required')}${field('Vencimento','due',x.due,'date')}${area('Detalhes do custo / combinado','notes',x.notes)}</div><p class="notice">Este cadastro registra um custo previsto. Use “Registrar pagamento” quando a despesa for paga.</p>`,'assignment')}
function teamTotals(pid){const all=(state.assignments||[]).filter(a=>a.projectId===pid);return {planned:all.reduce((n,a)=>n+a.amount,0),pending:all.filter(a=>!a.transactionId).reduce((n,a)=>n+a.amount,0),paid:all.reduce((n,a)=>n+(state.transactions.find(t=>t.id===a.transactionId)?.amount||0),0)}}
function teamPage(){const p=project(selected);if(!p)return empty('Trabalho não encontrado','Volte à lista.','nav:projects');const t=teamTotals(p.id);return btn('Voltar ao trabalho','project:'+p.id,'back')+header('Equipe e custos',esc(p.name),btn('Adicionar parceiro','assign:'+p.id,'plus','primary'))+`<div class="summary-strip"><button><b>${money(t.planned)}</b>contratado / previsto</button><button><b>${money(t.paid)}</b>pago a parceiros</button><button><b>${money(t.pending)}</b>pendente de pagamento</button></div><div class="grid cols2 section">${(state.assignments||[]).filter(a=>a.projectId===p.id).map(a=>{const v=state.partners.find(x=>x.id===a.partnerId);return `<article class="card"><div class="between"><h3>${esc(v.name)}</h3>${badge(a.transactionId?'Pago':'A pagar')}</div><p>${esc(a.service)}</p><p>${a.quantity} × ${money(a.rate)} + ${money(a.extraCost)} adicionais</p><strong>${money(a.amount)}</strong><p class="note">Vencimento: ${fmt(a.due)}<br>${esc(a.notes)}</p>${waButton(v,p)}${a.transactionId?'<p class="positive">Pagamento registrado no Financeiro.</p>':btn('Registrar pagamento','pay-assignment:'+a.id,'wallet','primary')}${actions('edit-assignment:'+a.id,'delete-assignment:'+a.id)}</article>`}).join('')||empty('Sem parceiros neste trabalho','Adicione equipe, locações e outros serviços.','assign:'+p.id,'Adicionar')}</div>`}
const v4Project=projectPage;
projectPage=function(){const p=project(selected);if(!p)return v4Project();const h=v4Project(),t=teamTotals(p.id);return h+`<section class="card section"><div class="between wrap"><div><h2>Equipe e custos de parceiros</h2><p class="note">Previsto: ${money(t.planned)} · A pagar: ${money(t.pending)} · Pago: ${money(t.paid)}</p></div>${btn('Gerenciar equipe e custos','team:'+p.id,'users','primary')}</div>${tab==='Valores'?'<p class="legend">Despesas pagas do projeto: '+money(totals(p.id).cost)+'. Os pagamentos dos parceiros já estão incluídos neste total.</p>':''}</section>`};
const v4Clients=clientsPage;
clientsPage=function(){let html=v4Clients();for(const c of state.clients)html=html.replace(actions('edit:client:'+c.id,'delete:client:'+c.id,btn('Ver cliente','client:'+c.id,'arrow')),waButton(c)+actions('edit:client:'+c.id,'delete:client:'+c.id,btn('Ver cliente','client:'+c.id,'arrow')));return html};
const stageColors={'Consulta':'#677570','Proposta':'#866b41','Confirmado':'#29766c','Preparação':'#af7625','Captação':'#a8513f','Pós-produção':'#625fa2','Aprovação':'#2b718b','Entrega':'#397148','Arquivado':'#757575','Cancelado':'#974747'};
const v4Card=workCard;
workCard=function(p){let h=v4Card(p),done=p.checks.filter(x=>x.done).length,total=p.checks.length;h=h.replace('class="card job-card"','class="card job-card" style="border-top:5px solid '+stageColors[p.stage]+'"');h=h.replace(badge(p.stage),`<span class="stage-label" style="background:${stageColors[p.stage]}">${esc(p.stage)}</span>`);return h.replace('<div class="job-footer">',`<div class="job-progress"><span>Tarefas ${done}/${total}</span><progress max="${total||1}" value="${done}"></progress>${p.due&&p.due<today()&&active(p)?'<b class="negative">Prazo geral vencido · confira as entregas</b>':''}</div><div class="job-footer">`)};
let stageFilter='';const v4Projects=projectsPage;
projectsPage=function(){let h=v4Projects();const visible=state.projects.filter(p=>(!filter||p.type===filter)&&(p.name+' '+client(p.clientId)?.name).toLowerCase().includes(query.toLowerCase())&&(!stageFilter||p.stage===stageFilter));return h.replace('<div class="toolbar">',`<div class="stage-filters">${['',...stages].map(s=>`<button class="${stageFilter===s?'selected':''}" data-action="filter-stage:${s}">${s||'Todas'} <b>${state.projects.filter(p=>!s||p.stage===s).length}</b></button>`).join('')}</div><div class="toolbar">`).replace(/<div class="grid cols3" id="results">[\s\S]*$/,`<div class="grid cols3" id="results">${visible.map(workCard).join('')||empty('Nenhum trabalho nesta etapa','Escolha outra etapa ou cadastre um trabalho.')}</div>`)};
function pendingItems(){const out=[],limit=addDays(7);for(const e of state.events)if(!e.done&&e.start.slice(0,10)<=limit)out.push({title:e.title,detail:(e.end<today()?'Atrasado / confirmar conclusão':'Agendado')+' · '+fmt(e.start.slice(0,10))+' '+e.start.slice(11),action:'event:'+e.id});for(const p of state.projects.filter(active)){for(const c of p.checks.filter(c=>!c.done))out.push({title:c.text,detail:p.name,action:'project-tasks:'+p.id});for(const d of p.deliveries.filter(d=>d.status!=='Entregue'&&d.due&&d.due<=limit))out.push({title:'Entrega: '+d.name,detail:p.name+' · '+fmt(d.due),action:'project:'+p.id})}for(const a of state.assignments||[])if(!a.transactionId&&a.due&&a.due<=limit)out.push({title:'Pagar parceiro: '+a.service,detail:money(a.amount)+' · '+fmt(a.due),action:'team:'+a.projectId});return out}
function notifications(){const items=pendingItems();modal('Avisos e pendências',`<p class="note">Compromissos até os próximos 7 dias, tarefas abertas, entregas e custos a vencer. Atualizados enquanto o app está aberto.</p>${items.map(x=>`<button class="notice-item" data-action="notice-open:${esc(x.action)}"><b>${esc(x.title)}</b><small>${esc(x.detail)}</small>${icon('arrow')}</button>`).join('')||'<p>Sem pendências no momento.</p>'}`)}
const v4Shell=shell;
shell=function(content){const n=pendingItems().length;return v4Shell(content).replace(/<button class="icon-btn" data-action="nav:home" aria-label="Pendências de hoje">[\s\S]*?<\/button>/,`<button class="icon-btn notification-bell" data-action="notifications" aria-label="${n} avisos e pendências">${icon('bell')}${n?'<span>'+Math.min(n,99)+'</span>':''}</button>`)};
navs.push(['partners','Parceiros','users']);
const v4More=morePage;morePage=function(){return v4More()+`<button class="card more-card section" data-action="nav:partners">${icon('users')}<span><b>Fornecedores e parceiros</b><small class="block">Contatos, equipe e custos por trabalho</small></span>${icon('arrow')}</button>`};
const v4Render=render;render=function(){if(state&&['partners','team'].includes(route)){$('#app').innerHTML=shell(route==='partners'?partnersPage():teamPage());return}v4Render()};
const v4EventRow=eventRow;eventRow=function(e){return v4EventRow(e)+`<div class="row wrap">${btn(e.done?'Reabrir compromisso':'Marcar como concluído','complete-event:'+e.id,'check')}${e.projectId?waButton(client(project(e.projectId)?.clientId),project(e.projectId)):''}</div>`};
function quoteItemRow(x={}){return `<div class="quote-item"><label>Serviço / entregável<input name="itemName" value="${esc(x.name||'')}" required placeholder="Ex.: cobertura fotográfica"></label><label>Qtd.<input name="itemQty" type="number" value="${x.quantity||1}" min="0.01" step="0.01" required></label>${field('Unitário (R$)','itemRate',((x.rate||0)/100).toFixed(2),'number','required').replace('type="number"','type="text" data-mask="money" inputmode="decimal"')}<button type="button" class="icon-btn danger" data-action="remove-quote-item" aria-label="Excluir item">${icon('trash')}</button></div>`}
quoteForm=function(id=null,pid=null){if(!state.clients.length){toast('Cadastre um cliente primeiro.');return openForm('client')}const q=(state.quotes||[]).find(q=>q.id===id)||{},p=project(pid||q.projectId),items=q.items||[{name:q.title||p?.type||'',quantity:1,rate:q.amount??p?.value??0}];modal(id?'Editar proposta':'Nova proposta detalhada',`<input type="hidden" name="id" value="${id||''}"><div class="grid cols2 form-cols"><h3 class="full">1. Cliente e produção</h3>${field('Título da proposta','title',q.title||p?.name||'','text','required maxlength="160"')}${select('Cliente','clientId',state.clients.map(c=>[c.id,c.name]),q.clientId||p?.clientId,'required')}${select('Trabalho vinculado (opcional)','projectId',[['','Sem vínculo'],...state.projects.map(p=>[p.id,p.name])],q.projectId||pid||'')}${select('Situação','status',['Rascunho','Enviada','Aceita','Recusada'],q.status||'Rascunho')}${field('Data do evento / sessão','eventDate',q.eventDate||p?.date,'date')}${field('Local','location',q.location||p?.location)}${field('Validade da proposta','validUntil',q.validUntil||addDays(15),'date','required')}${field('Prazo de entrega','deliveryDate',q.deliveryDate||p?.due,'date')}</div><h3 class="section">2. Serviços e valores</h3><div id="quote-items">${items.map(quoteItemRow).join('')}</div>${btn('Adicionar item','add-quote-item','plus')}<div class="grid cols2 form-cols section">${field('Desconto (R$)','discount',((q.discount||0)/100).toFixed(2),'number','required')}${field('Deslocamento / adicionais (R$)','extraCost',((q.extraCost||0)/100).toFixed(2),'number','required')}</div><div id="quote-total" class="quote-total" aria-live="polite">Total calculado ao salvar</div><h3 class="section">3. Escopo e condições</h3>${area('Descrição do serviço e entregas','scope',q.scope||p?.brief||'','required placeholder="Quantidade de fotos, duração do vídeo, horas de cobertura…"')}${area('Forma e condições de pagamento','paymentTerms',q.paymentTerms||'','placeholder="Ex.: 30% na reserva e restante até a data do evento."')}${area('Revisões incluídas e serviços extras','revisions',q.revisions||'')}${area('Reagendamento / cancelamento','cancellation',q.cancellation||'')}${area('Observações para o cliente','clientNotes',q.clientNotes||'')}<p class="legend">O PDF inclui seu logo e os dados do cadastro. A situação de aceite é registrada manualmente.</p>`,'quote','Salvar proposta');refreshQuoteTotal()};
function readQuoteItems(f){return [...f.querySelectorAll('.quote-item')].map(row=>({name:row.querySelector('[name=itemName]').value.trim(),quantity:Number(row.querySelector('[name=itemQty]').value),rate:parseMoney(row.querySelector('[name=itemRate]').value)}))}
function quoteAmount(items,discount,extra){if(!items.length||items.some(i=>!i.name||!Number.isFinite(i.quantity)||i.quantity<=0||i.quantity>100000||!Number.isSafeInteger(i.rate)||i.rate<0))throw Error('Preencha os serviços, quantidades e valores.');const sum=items.reduce((n,i)=>n+Math.round(i.quantity*i.rate),0);if(discount>sum+extra)throw Error('O desconto não pode superar o total.');return sum+extra-discount}
function refreshQuoteTotal(){const f=$('#form'),box=$('#quote-total');if(!f||!box)return;try{const items=readQuoteItems(f),discount=parseMoney(f.querySelector('[name=discount]').value),extra=parseMoney(f.querySelector('[name=extraCost]').value);box.textContent='Total da proposta: '+money(quoteAmount(items,discount,extra))}catch{box.textContent='Preencha os itens para calcular o total.'}}
const v4Profile=profileForm;profileForm=function(){v4Profile();const f=$('#form');f?.insertAdjacentHTML('afterbegin','<div class=\"grid cols2 form-cols\">'+identityFields(state.profile).replace(/<label>Cidade[\s\S]*?<\/label>/,'')+'</div>')};
const v4Submit=submit;
submit=async function(kind,f){const v=Object.fromEntries([...new FormData(f)].filter(([k])=>!['coverFile','logoFile'].includes(k)));if(kind==='profile')validateIdentity(v);if(kind==='client'||kind==='partner'){validateIdentity(v);v.document=digits(v.document);v.cep=digits(v.cep);v.phone=digits(v.phone);v.uf=(v.uf||'').toUpperCase();v.type=v.personType==='PJ'?'Empresa':'Pessoa';if(kind==='partner'){if(!v.name.trim())throw Error('Informe o nome.');const obj={...v,id:v.id||uid(),name:v.name.trim()};await commit(d=>{d.partners??=[];const i=d.partners.findIndex(x=>x.id===obj.id);i<0?d.partners.push(obj):d.partners.splice(i,1,obj)},'Parceiro salvo');closeModal(true);go('partners');return}for(const k of ['document','cep','phone','uf','type']){const el=f.querySelector('[name='+k+']');if(el)el.value=v[k]}}
if(kind==='assignment'){const old=(state.assignments||[]).find(a=>a.id===v.id);if(old?.transactionId)throw Error('Este custo já está pago. Desfaça o pagamento antes de editar.');const quantity=Number(v.quantity),rate=parseMoney(v.rate),extraCost=parseMoney(v.extraCost);if(!v.service.trim()||!Number.isFinite(quantity)||quantity<=0||quantity>100000)throw Error('Confira serviço e quantidade.');const a={...v,id:v.id||uid(),quantity,rate,extraCost,amount:Math.round(quantity*rate)+extraCost,transactionId:''};await commit(d=>{d.assignments??=[];const i=d.assignments.findIndex(x=>x.id===a.id);i<0?d.assignments.push(a):d.assignments.splice(i,1,a)},'Custo de parceiro salvo');closeModal(true);go('team',a.projectId);return}
if(kind==='pay-assignment'&&!/^\d{4}-\d{2}-\d{2}$/.test(v.date))throw Error('Informe a data do pagamento.');if(kind==='pay-assignment'){const a=state.assignments.find(a=>a.id===v.id);if(a.transactionId)throw Error('Pagamento já registrado.');const tid=uid();await commit(d=>{const x=d.assignments.find(x=>x.id===a.id);d.transactions.push({id:tid,projectId:x.projectId,type:'Despesa',amount:x.amount,date:v.date,description:'Parceiro: '+d.partners.find(p=>p.id===x.partnerId).name+' · '+x.service,competence:v.date.slice(0,7),category:'Equipe e parceiros',account:(d.financeConfig?.accounts||['Conta principal'])[0],paymentMethod:'Pix',document:'',notes:''});x.transactionId=tid},'Pagamento de parceiro registrado');closeModal(true);toast('Despesa registrada uma única vez.');return}
if(kind==='quote'&&f.querySelector?.('#quote-items')){const items=readQuoteItems(f),discount=parseMoney(v.discount),extraCost=parseMoney(v.extraCost),amount=quoteAmount(items,discount,extraCost);if(!v.title.trim()||!v.scope.trim())throw Error('Preencha título e descrição.');if(v.projectId&&project(v.projectId)?.clientId!==v.clientId)throw Error('O trabalho pertence a outro cliente.');const q={...v,id:v.id||uid(),items,discount,extraCost,amount};delete q.itemName;delete q.itemQty;delete q.itemRate;await commit(d=>{d.quotes??=[];const i=d.quotes.findIndex(x=>x.id===q.id);i<0?d.quotes.push(q):d.quotes.splice(i,1,q)},'Proposta detalhada salva');closeModal(true);go('quotes');toast('Proposta salva. Use Gerar PDF no cartão.');return}
return v4Submit(kind,f)};
const v4Action=action;
action=async function(a){const [cmd,id]=a.split(':');if(cmd==='notifications')return notifications();if(cmd==='notice-open'){closeModal(true);return action(a.slice(12))}if(cmd==='filter-stage'){stageFilter=id;render();return}if(cmd==='complete-event'){await commit(d=>{const e=d.events.find(x=>x.id===id);e.done=!e.done},'Situação do compromisso atualizada');return}if(cmd==='new-partner')return partnerForm();if(cmd==='edit-partner')return partnerForm(id);if(cmd==='delete-partner'){if((state.assignments||[]).some(a=>a.partnerId===id))throw Error('Este parceiro está vinculado a trabalhos. Remova os vínculos antes de excluir.');if(confirm('Excluir este fornecedor / parceiro?'))await commit(d=>d.partners=d.partners.filter(p=>p.id!==id),'Parceiro excluído');return}if(cmd==='team'){go('team',id);return}if(cmd==='assign')return assignmentForm(id);if(cmd==='edit-assignment'){const x=state.assignments.find(x=>x.id===id);if(x.transactionId)throw Error('Use Desfazer pagamento antes de editar o custo.');return assignmentForm(x.projectId,id)}if(cmd==='pay-assignment'){const x=state.assignments.find(x=>x.id===id);if(x.transactionId)throw Error('Já pago.');if(x.amount<=0)throw Error('O custo deve ser maior que zero.');modal('Registrar pagamento',`<input name="id" type="hidden" value="${id}"><p>${esc(x.service)} · <b>${money(x.amount)}</b></p>${field('Data efetiva do pagamento','date',today(),'date','required')}`,'pay-assignment');return}if(cmd==='undo-assignment'){if(!confirm('Remover o lançamento financeiro e voltar o custo para a pagar?'))return;await commit(d=>{const x=d.assignments.find(x=>x.id===id);d.transactions=d.transactions.filter(t=>t.id!==x.transactionId);x.transactionId=''},'Pagamento desfeito');return}if(cmd==='delete-assignment'){if(!confirm('Excluir este custo e, se pago, remover também sua despesa do Financeiro?'))return;await commit(d=>{const x=d.assignments.find(x=>x.id===id);d.transactions=d.transactions.filter(t=>t.id!==x.transactionId);d.assignments=d.assignments.filter(x=>x.id!==id)},'Custo de parceiro excluído');return}if((cmd==='transaction'||a.startsWith('delete:transaction:'))&&(state.assignments||[]).some(x=>x.transactionId===(cmd==='transaction'?id:a.split(':')[2])))throw Error('Este lançamento vem de um parceiro. Em Equipe e custos, use Desfazer pagamento para corrigir.');if(cmd==='add-quote-item'){document.querySelector('#quote-items').insertAdjacentHTML('beforeend',quoteItemRow());dirty=true;return}if(cmd==='remove-quote-item')return;return v4Action(a)};
// Integração de exclusão de projeto: elimina também seus custos relacionados.
const v4Commit=commit;
commit=async function(fn,label){return v4Commit(d=>{fn(d);if(d.assignments)d.assignments=d.assignments.filter(a=>d.projects.some(p=>p.id===a.projectId))},label)};
const v4TeamPage=teamPage;teamPage=function(){let h=v4TeamPage();for(const a of state.assignments||[])if(a.projectId===selected&&a.transactionId)h=h.replace(actions('edit-assignment:'+a.id,'delete-assignment:'+a.id),actions('edit-assignment:'+a.id,'delete-assignment:'+a.id,btn('Desfazer pagamento','undo-assignment:'+a.id,'wallet')));return h};
const v4PDF=openPDF;
openPDF=async function(kind,item){if(kind!=='quote'||!item?.items)return v4PDF(kind,item);const c=client(item.clientId),address=[c.street,c.number,c.complement,c.district,c.city,c.uf,c.cep?'CEP '+c.cep:''].filter(Boolean).join(' · ');const details=[c.document?'CPF/CNPJ: '+maskDoc(c.document):'',address,item.eventDate?'Data do evento: '+fmt(item.eventDate):'',item.location?'Local: '+item.location:'',item.deliveryDate?'Entrega: '+fmt(item.deliveryDate):'','SERVIÇOS CONTRATADOS',...item.items.map((i,n)=>(n+1)+'. '+i.name+' — '+i.quantity+' × '+money(i.rate)+' = '+money(Math.round(i.quantity*i.rate))),'Desconto: '+money(item.discount||0),'Adicionais: '+money(item.extraCost||0),'ESCOPO',item.scope,item.paymentTerms?'PAGAMENTO\n'+item.paymentTerms:'',item.revisions?'REVISÕES E EXTRAS\n'+item.revisions:'',item.cancellation?'REAGENDAMENTO / CANCELAMENTO\n'+item.cancellation:'',item.clientNotes?'OBSERVAÇÕES\n'+item.clientNotes:''].filter(Boolean).join('\n\n');return v4PDF(kind,{...item,scope:details})};
