function pdfByte(c){const n=c.codePointAt(0);if(n<=255)return n;const map={'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};return map[c]||63}
function pdfHex(s){return '<'+Array.from(String(s).normalize('NFC'),c=>pdfByte(c).toString(16).padStart(2,'0')).join('')+'>'}
function pdfWidth(s,size,bold=false){const w=pdfFontWidths[bold?'Helvetica-Bold':'Helvetica'];return Array.from(String(s).normalize('NFC')).reduce((n,c)=>n+w[pdfByte(c)]*size/1000,0)}
function selectablePdf(kind,item,pro,customer,logo=null){
 const W=595.276,H=841.89,L=46,R=W-L,contentW=R-L,pages=[];let ops=[],y=0,page=0;
 const color=(c)=>[0,2,4].map(i=>parseInt(c.slice(i,i+2),16)/255).map(n=>n.toFixed(3)).join(' ');
 const rect=(x,top,w,h,c)=>ops.push(`${color(c)} rg ${x} ${H-top-h} ${w} ${h} re f`);
 const rule=(top)=>{ops.push(`${color('d5c5b1')} RG 0.7 w ${L} ${H-top} m ${R} ${H-top} l S`)};
 const draw=(t,x,top,size=11,bold=false,c='26362f')=>ops.push(`BT /${bold?'F2':'F1'} ${size} Tf ${color(c)} rg 1 0 0 1 ${x} ${H-top} Tm ${pdfHex(t)} Tj ET`);
 const finish=()=>{rule(790);ops.push('q 132 0 0 30 '+L+' 16 cm /LensBrand Do Q');draw('Gerado no LENS CORE STUDIO',L+145,809,7,false,'6c756d');draw(String(page),R-12,808,8,false,'6c756d');pages.push(ops.join('\n'))};
 const start=()=>{page++;ops=[];draw(String(pro.name).slice(0,60),L,42,14,true);draw(kind==='quote'?'PROPOSTA COMERCIAL':'CONTRATO',R-135,42,8,true,'957247');rule(56);y=82};
 const ensure=h=>{if(y+h>766){finish();start()}};
 const lines=(s,size,bold)=>{const result=[];for(const para of String(s||'').split('\n')){let row='';for(let word of para.split(/\s+/)){if(row&&pdfWidth(row+' '+word,size,bold)>contentW){result.push(row);row=''}while(pdfWidth(word,size,bold)>contentW){let n=1;while(n<word.length&&pdfWidth(word.slice(0,n+1),size,bold)<=contentW)n++;result.push(word.slice(0,n));word=word.slice(n)}row+=(row?' ':'')+word}result.push(row)}return result};
 const text=(s,size=11,bold=false,c='26362f')=>{for(const row of lines(s,size,bold)){ensure(size+7);draw(row,L,y,size,bold,c);y+=size+6}};
 const section=t=>{ensure(65);y+=13;rule(y);y+=22;text(t,11,true,'957247');y+=2};
 start();if(logo){const scale=Math.min(115/logo.width,55/logo.height);const w=logo.width*scale,h=logo.height*scale;ops.push(`q ${w} 0 0 ${h} ${L} ${H-y-h} cm /Logo Do Q`);y+=h+20}
 text(item.title,23,true);y+=6;text(pro.owner||'',10);text([pro.phone,pro.email,pro.city].filter(Boolean).join(' · '),9,false,'647268');
 section('CLIENTE');text(customer.name,12,true);if(customer.document)text((customer.personType==='PJ'?'CNPJ: ':'CPF: ')+maskDoc(customer.document),10);text([customer.phone,customer.email].filter(Boolean).join(' · '),10);text([customer.street,customer.number,customer.complement,customer.district,customer.city,customer.uf,customer.cep?'CEP '+customer.cep:''].filter(Boolean).join(' · '),9);
 if(kind==='quote'){
  section('PRODUÇÃO E PRAZOS');text('Validade da proposta: '+fmt(item.validUntil),10);if(item.eventDate)text('Evento / sessão: '+fmt(item.eventDate),10);if(item.location)text('Local: '+item.location,10);if(item.deliveryDate)text('Entrega: '+fmt(item.deliveryDate),10);
  if(item.items?.length){section('SERVIÇOS E INVESTIMENTO');item.items.forEach((it,i)=>{ensure(48);text((i+1)+'. '+it.name,11,true);text(it.quantity+' × '+money(it.rate)+'  |  '+money(Math.round(it.quantity*it.rate)),10,false,'647268');y+=5});text('Desconto: '+money(item.discount||0)+'  ·  Adicionais: '+money(item.extraCost||0),10);}
  ensure(64);y+=10;rect(L,y-5,contentW,44,'eee7dd');draw('VALOR TOTAL',L+14,y+12,9,true,'6a5640');draw(money(item.amount),R-pdfWidth(money(item.amount),19,true)-14,y+23,19,true);y+=57;
  for(const [title,value] of [['ESCOPO E ENTREGAS',item.scope],['PAGAMENTO',item.paymentTerms],['REVISÕES E SERVIÇOS EXTRAS',item.revisions],['REAGENDAMENTO E CANCELAMENTO',item.cancellation],['OBSERVAÇÕES',item.clientNotes]])if(value){section(title);text(value)}
  y+=15;text('Proposta emitida pelo profissional. Não comprova aceite ou pagamento.',8,false,'647268');
 }else{section('CONDIÇÕES DO CONTRATO');text(item.text);ensure(115);y+=45;rule(y);y+=20;text(pro.owner||pro.name,10);text(customer.name+' · Cliente',10);text('Documento sem assinatura eletrônica aplicada.',8,false,'647268')}
 finish();return encodeTextPdf(pages,logo);
}
function encodeTextPdf(pages,logo){const enc=new TextEncoder(),parts=[],off=[0];let length=0;const put=x=>{const b=typeof x==='string'?enc.encode(x):x;parts.push(b);length+=b.length};const obj=(id,s)=>{off[id]=length;put(id+' 0 obj\n'+s+'\nendobj\n')};put('%PDF-1.4\n');const first=logo?11:10;obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Count '+pages.length+' /Kids ['+pages.map((_,i)=>(first+2*i)+' 0 R').join(' ')+'] >>');embeddedPdfFonts.forEach((f,i)=>{obj(3+i,'<< /Type /Font /Subtype /TrueType /BaseFont /'+f.name+' /FirstChar 32 /LastChar 255 /Widths ['+f.widths.slice(32).join(' ')+'] /FontDescriptor '+(5+i)+' 0 R /Encoding /WinAnsiEncoding >>');obj(5+i,'<< /Type /FontDescriptor /FontName /'+f.name+' /Flags 32 /FontBBox ['+f.bbox.join(' ')+'] /ItalicAngle 0 /Ascent '+f.ascent+' /Descent '+f.descent+' /CapHeight 700 /StemV '+(i?120:80)+' /FontFile2 '+(7+i)+' 0 R >>');const data=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0));off[7+i]=length;put((7+i)+' 0 obj\n<< /Length '+data.length+' /Length1 '+data.length+' >>\nstream\n');put(data);put('\nendstream\nendobj\n')});{const brand=LENS_BRAND.pdf,bytes=Uint8Array.from(atob(brand.data.split(',')[1]),c=>c.charCodeAt(0));off[9]=length;put('9 0 obj\n<< /Type /XObject /Subtype /Image /Width '+brand.width+' /Height '+brand.height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+bytes.length+' >>\nstream\n');put(bytes);put('\nendstream\nendobj\n')}if(logo){const bytes=Uint8Array.from(atob(logo.data.split(',')[1]),c=>c.charCodeAt(0));off[10]=length;put('10 0 obj\n<< /Type /XObject /Subtype /Image /Width '+logo.width+' /Height '+logo.height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+bytes.length+' >>\nstream\n');put(bytes);put('\nendstream\nendobj\n')}
 pages.forEach((stream,i)=>{const n=first+i*2;obj(n,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.276 841.89] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> '+('/XObject << /LensBrand 9 0 R '+(logo?'/Logo 10 0 R ':'')+'>> ')+'>> /Contents '+(n+1)+' 0 R >>');obj(n+1,'<< /Length '+enc.encode(stream).length+' >>\nstream\n'+stream+'\nendstream')});const xref=length,count=first+2*pages.length;put('xref\n0 '+count+'\n0000000000 65535 f \n');for(let i=1;i<count;i++)put(String(off[i]).padStart(10,'0')+' 00000 n \n');put('trailer\n<< /Size '+count+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF');return new Blob(parts,{type:'application/pdf'})}
openPDF=async function(kind,item){if(!item)throw Error('Salve o documento primeiro.');const c=client(item.clientId);if(!c)throw Error('Cliente não encontrado.');let logo=null;if(state.profile.logo){const im=new Image();im.src=state.profile.logo;await im.decode();const cv=document.createElement('canvas');cv.width=im.width;cv.height=im.height;const ctx=cv.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(im,0,0);logo={width:cv.width,height:cv.height,data:cv.toDataURL('image/jpeg',.95)}}const blob=selectablePdf(kind,item,state.profile,c,logo),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(kind==='quote'?'Proposta-':'Contrato-')+item.title.replace(/[^\p{L}\p{N} -]/gu,'').slice(0,70)+'.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('PDF A4 com texto selecionável gerado.')};
/* V0.5 — parcelas e endereço por CEP */
function validDay(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&localDate(new Date(s+'T12:00:00'))===s}
function addMonthsClamped(date,n){const [y,m,d]=date.split('-').map(Number),v=new Date(y,m-1+n,1,12);v.setDate(Math.min(d,new Date(v.getFullYear(),v.getMonth()+1,0).getDate()));return localDate(v)}
function splitCents(total,count){const base=Math.floor(total/count),rest=total%count;return Array.from({length:count},(_,i)=>base+(i<rest?1:0))}
function installmentRemaining(pid,aid='',exclude=''){const p=project(pid);if(!p)return 0;const assignment=(state.assignments||[]).find(a=>a.id===aid),target=assignment?assignment.amount:p.value;const paid=assignment?(assignment.transactionId?(state.transactions.find(t=>t.id===assignment.transactionId)?.amount||0):0)+(state.installments||[]).filter(s=>s.assignmentId===aid&&s.transactionId).reduce((n,s)=>n+s.amount,0):totals(pid).paid;const planned=(state.installments||[]).filter(s=>s.projectId===pid&&(aid?s.assignmentId===aid:!s.assignmentId)&&!s.transactionId&&s.id!==exclude).reduce((n,s)=>n+s.amount,0);return Math.max(0,target-paid-planned)}
const v5Validate=validate;
validate=function(d){v5Validate(d);d.installments??=[];if(!Array.isArray(d.installments)||d.installments.length>30000)throw Error('Parcelas inválidas.');const ids=new Set(),payments=new Set((d.assignments||[]).map(a=>a.transactionId).filter(Boolean));for(const s of d.installments){if(!s||!/^[-\w]{1,100}$/.test(s.id)||ids.has(s.id)||!d.projects.some(p=>p.id===s.projectId)||!Number.isSafeInteger(s.amount)||s.amount<=0||!validDay(s.due)||typeof s.description!=='string')throw Error('Parcela inválida.');ids.add(s.id);if(s.assignmentId&&!d.assignments.some(a=>a.id===s.assignmentId&&a.projectId===s.projectId&&!a.transactionId))throw Error('Parceiro inválido ou já pago integralmente.');if(s.transactionId){if(payments.has(s.transactionId))throw Error('Pagamento repetido entre parcelas.');payments.add(s.transactionId);const t=d.transactions.find(t=>t.id===s.transactionId);if(!t||t.amount!==s.amount||t.projectId!==s.projectId||t.type!==(s.assignmentId?'Despesa':'Recebimento'))throw Error('Lançamento da parcela inválido.')}}
for(const a of d.assignments||[]){const list=d.installments.filter(s=>s.assignmentId===a.id);if(list.reduce((n,s)=>n+s.amount,0)>a.amount)throw Error('Parcelas superam o custo do parceiro.');}
for(const p of d.projects){const unpaid=d.installments.filter(s=>s.projectId===p.id&&!s.assignmentId&&!s.transactionId).reduce((n,s)=>n+s.amount,0),paid=d.transactions.filter(t=>t.projectId===p.id).reduce((n,t)=>n+(t.type==='Recebimento'?t.amount:t.type==='Estorno'?-t.amount:0),0);if(unpaid>Math.max(0,p.value-paid))throw Error('Parcelas em aberto superam o saldo do trabalho. Ajuste o planejamento de parcelas antes deste lançamento.');}return d};
function installmentsForm(pid,aid='',id=''){const s=(state.installments||[]).find(s=>s.id===id),available=installmentRemaining(pid,aid,id);if(s?.transactionId)throw Error('Desfaça a baixa antes de editar.');modal(id?'Editar parcela':'Planejar parcelas',`<input type="hidden" name="id" value="${id}"><input type="hidden" name="projectId" value="${pid}"><input type="hidden" name="assignmentId" value="${aid}"><p class="notice">${aid?'Pagamento ao parceiro':'Recebimento do cliente'} · disponível para planejar: <b>${money(available)}</b></p><div class="grid cols2 form-cols">${field('Descrição','description',s?.description||(aid?'Pagamento de serviço':'Recebimento do trabalho'),'text','required maxlength="160"')}${field(id?'Valor da parcela (R$)':'Total a parcelar (R$)','amount',((s?.amount??available)/100).toFixed(2),'number','required')}${id?'':field('Número de parcelas mensais','count',1,'number','min="1" max="36" required')}${field(id?'Vencimento':'Primeiro vencimento','due',s?.due||today(),'date','required')}</div><p class="legend">Centavos são distribuídos sem alterar o total. Meses mais curtos usam o último dia do mês. O caixa só muda ao confirmar a baixa.</p>`,'installments')}
let installmentPartner='';
function installmentRows(list){return list.map(s=>{const p=project(s.projectId),a=(state.assignments||[]).find(a=>a.id===s.assignmentId),partner=a?state.partners.find(p=>p.id===a.partnerId):null;return `<article class="card installment-record"><div class="between"><div><small>${s.assignmentId?'A PAGAR':'A RECEBER'} · ${esc(p?.name)}</small><h3>${esc(s.description)}</h3></div><strong>${money(s.amount)}</strong></div><p>${esc(partner?.name||client(p?.clientId)?.name)} · ${fmt(s.due)}</p>${badge(s.transactionId?(s.assignmentId?'Pago':'Recebido'):s.due<today()?'Vencido':s.due===today()?'Vence hoje':'Em aberto')}${waButton(partner||client(p?.clientId),p)}${actions('edit-installment:'+s.id,'delete-installment:'+s.id,s.transactionId?btn('Desfazer baixa','undo-installment:'+s.id,'back'):btn(s.assignmentId?'Registrar pagamento':'Registrar recebimento','settle-installment:'+s.id,'wallet','primary'))}</article>`}).join('')||empty('Nenhuma parcela','Planeje os vencimentos de um trabalho ou parceiro.')}
function installmentsPage(){const p=project(selected),all=state.installments||[],list=all.filter(s=>(!p||s.projectId===p.id)&&(!installmentPartner||s.assignmentId===installmentPartner)).sort((a,b)=>a.due.localeCompare(b.due));return (p?btn('Voltar ao trabalho','project:'+p.id,'back'):'')+header('Parcelas e vencimentos',p?esc(p.name):'Recebimentos e pagamentos planejados.',p?btn('Planejar parcelas','plan-installments:'+p.id+':'+installmentPartner,'plus','primary'):'')+`<p class="notice">Somente parcelas baixadas entram no caixa. Em aberto e vencidas continuam como previsão.</p><div class="grid cols2">${installmentRows(list)}</div>`}
const v5Finance=financePage;financePage=function(){return v5Finance()+`<section class="card section"><div class="between wrap"><div><h2>Parcelas e vencimentos</h2><p class="note">${(state.installments||[]).filter(s=>!s.transactionId).length} parcelas em aberto</p></div>${btn('Ver todas as parcelas','all-installments','calendar','primary')}</div></section>`};
const v5Project=projectPage;projectPage=function(){const h=v5Project(),p=project(selected);if(!p)return h;return h+`<section class="card section"><h2>Recebimentos parcelados</h2><p class="note">Organize sinal, parcelas e saldo final do cliente.</p><div class="row wrap">${btn('Planejar recebimentos','plan-installments:'+p.id,'plus','primary')}${btn('Ver parcelas','show-installments:'+p.id,'calendar')}</div></section>`};
const v5TeamTotals=teamTotals;teamTotals=function(pid){const t=v5TeamTotals(pid),paid=(state.installments||[]).filter(s=>s.assignmentId&&s.projectId===pid&&s.transactionId).reduce((n,s)=>n+s.amount,0);return {...t,paid:t.paid+paid,pending:Math.max(0,t.pending-paid)}};
const v5Team=teamPage;teamPage=function(){let h=v5Team();for(const a of state.assignments||[]){if(a.projectId!==selected)continue;const ps=(state.installments||[]).filter(s=>s.assignmentId===a.id);if(!a.transactionId){h=h.replace(btn('Registrar pagamento','pay-assignment:'+a.id,'wallet','primary'),(ps.length?'':btn('Pagar integralmente','pay-assignment:'+a.id,'wallet'))+btn(ps.length?'Ver parcelas':'Parcelar custo',ps.length?'show-installments:'+a.projectId+':'+a.id:'plan-installments:'+a.projectId+':'+a.id,'calendar','primary'));h=h.replace(actions('edit-assignment:'+a.id,'delete-assignment:'+a.id),'<p class="note">Parcelas pagas: '+money(ps.filter(s=>s.transactionId).reduce((n,s)=>n+s.amount,0))+' de '+money(a.amount)+'</p>'+actions('edit-assignment:'+a.id,'delete-assignment:'+a.id));}}return h};
const v5Render=render;render=function(){if(state&&route==='installments'){$('#app').innerHTML=shell(installmentsPage());return}return v5Render()};
const v5Pending=pendingItems;pendingItems=function(){const list=v5Pending().filter(x=>!((state.assignments||[]).some(a=>x.title==='Pagar parceiro: '+a.service&&(state.installments||[]).some(s=>s.assignmentId===a.id))));for(const s of state.installments||[])if(!s.transactionId&&s.due<=addDays(7))list.push({title:(s.assignmentId?'Pagar: ':'Receber: ')+s.description,detail:money(s.amount)+' · '+fmt(s.due),action:'show-installments:'+s.projectId+(s.assignmentId?':'+s.assignmentId:'')});return list};
const v5Commit=commit;commit=async function(fn,label){return v5Commit(d=>{fn(d);if(d.installments)d.installments=d.installments.filter(s=>d.projects.some(p=>p.id===s.projectId))},label)};
const v5Submit=submit;
submit=async function(kind,f){const v=Object.fromEntries([...new FormData(f)].filter(([k])=>!['coverFile','logoFile'].includes(k)));if(kind==='installments'){const total=parseMoney(v.amount),count=v.id?1:Number(v.count);if(!Number.isInteger(count)||count<1||count>36||total<count||!validDay(v.due)||!v.description.trim())throw Error('Confira valor, quantidade (1 a 36), descrição e data.');const amounts=splitCents(total,count);if(total>installmentRemaining(v.projectId,v.assignmentId,v.id))throw Error('O total supera o saldo disponível para planejar.');await commit(d=>{d.installments??=[];if(v.id){const old=d.installments.find(s=>s.id===v.id);if(!old||old.transactionId)throw Error('Parcela já baixada ou não encontrada.');Object.assign(old,{description:v.description.trim(),amount:total,due:v.due})}else amounts.forEach((amount,i)=>d.installments.push({id:uid(),projectId:v.projectId,assignmentId:v.assignmentId||'',description:v.description.trim()+(count>1?' · '+(i+1)+'/'+count:''),amount,due:addMonthsClamped(v.due,i),transactionId:''}))},'Parcelas planejadas');closeModal(true);installmentPartner=v.assignmentId||'';go('installments',v.projectId);return}
if(kind==='settle-installment'){if(!validDay(v.date))throw Error('Informe a data efetiva.');await commit(d=>{const s=d.installments.find(s=>s.id===v.id);if(!s||s.transactionId)throw Error('Parcela já baixada ou não encontrada.');const id=uid();d.transactions.push({id,projectId:s.projectId,type:s.assignmentId?'Despesa':'Recebimento',amount:s.amount,date:v.date,description:s.description,competence:v.date.slice(0,7),category:s.assignmentId?'Equipe e parceiros':'Parcela do cliente',account:(d.financeConfig?.accounts||['Conta principal'])[0],paymentMethod:'Pix',document:'',notes:''});s.transactionId=id},'Baixa de parcela registrada');closeModal(true);toast('Baixa registrada no Financeiro.');return}if(kind==='assignment'&&(state.installments||[]).some(s=>s.assignmentId===v.id))throw Error('Remova as parcelas deste custo antes de alterar o valor combinado.');if(kind==='pay-assignment'&&(state.installments||[]).some(s=>s.assignmentId===v.id))throw Error('Este custo foi parcelado. Registre os pagamentos em Ver parcelas.');return v5Submit(kind,f)};
const v5Action=action;
action=async function(a){const [cmd,id,arg]=a.split(':');if(cmd==='lookup-cep')return lookupCEP();if(cmd==='plan-installments')return installmentsForm(id,arg||'');if(cmd==='show-installments'){installmentPartner=arg||'';go('installments',id);return}if(cmd==='all-installments'){installmentPartner='';go('installments');return}if(cmd==='edit-installment'){const s=state.installments.find(s=>s.id===id);return installmentsForm(s.projectId,s.assignmentId,id)}if(cmd==='settle-installment'){const s=state.installments.find(s=>s.id===id);if(s.transactionId)throw Error('Parcela já baixada.');modal(s.assignmentId?'Registrar pagamento':'Registrar recebimento',`<input type="hidden" name="id" value="${id}"><p>${esc(s.description)} · <b>${money(s.amount)}</b></p>${field('Data efetiva','date',today(),'date','required')}`,'settle-installment');return}if(cmd==='undo-installment'||cmd==='delete-installment'){if(!confirm(cmd==='undo-installment'?'Desfazer a baixa e remover seu lançamento financeiro?':'Excluir esta parcela e seu lançamento financeiro, caso exista?'))return;await commit(d=>{const s=d.installments.find(s=>s.id===id);d.transactions=d.transactions.filter(t=>t.id!==s.transactionId);if(cmd==='delete-installment')d.installments=d.installments.filter(s=>s.id!==id);else s.transactionId=''},cmd==='delete-installment'?'Parcela excluída':'Baixa desfeita');return}if(cmd==='delete-assignment'&&(state.installments||[]).some(s=>s.assignmentId===id)){if(!confirm('Excluir este custo, todas as suas parcelas e os pagamentos registrados?'))return;await commit(d=>{const ids=d.installments.filter(s=>s.assignmentId===id).map(s=>s.transactionId);d.transactions=d.transactions.filter(t=>!ids.includes(t.id));d.installments=d.installments.filter(s=>s.assignmentId!==id);d.assignments=d.assignments.filter(x=>x.id!==id)},'Custo parcelado excluído');return}if((cmd==='transaction'||a.startsWith('delete:transaction:'))&&(state.installments||[]).some(s=>s.transactionId===(cmd==='transaction'?id:arg)))throw Error('Este lançamento pertence a uma parcela. Use Desfazer baixa em Parcelas e vencimentos.');return v5Action(a)};
const v5Field=field;field=function(label,name,value='',type='text',extra=''){const h=v5Field(label,name,value,type,extra);return name==='cep'?h+`<div class="cep-tools">${btn('Buscar endereço pelo CEP','lookup-cep','search')}<small id="cep-status" role="status">Consulta online. Você pode preencher manualmente.</small></div>`:h};
let cepSequence=0;
async function lookupCEP(){const form=$('#form'),input=form?.querySelector('[name=cep]'),status=$('#cep-status'),cep=digits(input?.value);if(cep.length!==8)throw Error('Digite um CEP com 8 números.');const seq=++cepSequence,names=['street','district','city','uf'],old=Object.fromEntries(names.map(k=>[k,form.querySelector('[name='+k+']')?.value||'']));if(status)status.textContent='Buscando endereço…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const res=await fetch('https://viacep.com.br/ws/'+cep+'/json/',{signal:controller.signal});if(!res.ok)throw Error();const data=await res.json();if(seq!==cepSequence||!form.isConnected||digits(input.value)!==cep)return;if(data.erro){status.textContent='CEP não encontrado. Confira ou preencha o endereço manualmente.';return}const values={street:data.logradouro,district:data.bairro,city:data.localidade,uf:data.uf};let preserved=false;for(const k of names){const el=form.querySelector('[name='+k+']');if(el&&el.value===old[k]&&typeof values[k]==='string')el.value=values[k];else if(el)preserved=true}dirty=true;status.textContent=preserved?'Endereço consultado. Mantive os campos que você alterou durante a busca.':'Endereço preenchido. Confira e informe número e complemento.'}catch{if(seq===cepSequence&&status?.isConnected)status.textContent='Não foi possível consultar agora. Preencha manualmente ou tente novamente.'}finally{clearTimeout(timer)}}
routeCovers.installments='desk';
const v5TeamStatus=teamPage;
teamPage=function(){return v5TeamStatus().replace(/<article class="card">[\s\S]*?<\/article>/g,card=>{const a=(state.assignments||[]).find(a=>card.includes('edit-assignment:'+a.id+'"'));if(!a)return card;const ps=(state.installments||[]).filter(s=>s.assignmentId===a.id),paid=ps.filter(s=>s.transactionId).reduce((n,s)=>n+s.amount,0);return card.replace(badge('A pagar'),badge(paid>=a.amount&&paid>0?'Pago':paid>0?'Pagamento parcial':'A pagar'))})};
/* V0.5.1 — cada informação no seu lugar. */
const homeBeforeLayout=homePage;
homePage=function(){const html=homeBeforeLayout();return html.slice(0,html.indexOf('<div class="next-capture">'))+'</div></section>'+html.slice(html.indexOf('<section class="control-section">'),html.indexOf('<div class="summary-strip">'))+'<p class="home-guide">Consulte seus horários na <button class="link-btn" data-action="nav:agenda">Agenda</button> e acompanhe cada produção em <button class="link-btn" data-action="nav:projects">Trabalhos</button>. Os avisos ficam no sino, no alto da tela.</p>'};
function compactActions(content){return `<details class="compact-actions"><summary>Mais ações</summary><div>${content}</div></details>`}
eventRow=function(e){const p=project(e.projectId);return `<article class="schedule-item"><div class="schedule-top"><div class="date-tile"><strong>${e.start.slice(8,10)}</strong><small>${new Date(e.start).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</small></div><div><span class="soft-chip ${e.done?'tone-income':'tone-cash'}">${e.done?'Concluído':esc(e.type)}</span><h3>${esc(e.title)}</h3><p class="event-time">${e.start.slice(11)} – ${e.end.slice(0,10)!==e.start.slice(0,10)?fmt(e.end.slice(0,10))+' · ':''}${e.end.slice(11)}</p></div></div><div class="event-meta">${e.location?`<p>${esc(e.location)}</p>`:''}${p?`<p>Trabalho: ${esc(p.name)}</p>`:''}</div><div class="item-controls">${btn('Editar','event:'+e.id,'edit')}${compactActions(btn(e.done?'Reabrir compromisso':'Concluir compromisso','complete-event:'+e.id,'check')+(p?waButton(client(p.clientId),p):'')+btn('Excluir','delete:event:'+e.id,'trash','danger'))}</div></article>`};
let agendaView='upcoming';const calendarBeforeLayout=agendaPage;
agendaPage=function(){const html=calendarBeforeLayout(),cut=html.indexOf('<section class="card section">');const es=state.events.filter(e=>agendaView==='day'?e.start.slice(0,10)<=chosen&&e.end.slice(0,10)>=chosen:agendaView==='done'?e.done:!e.done&&e.end.slice(0,10)>=today()).sort((a,b)=>a.start.localeCompare(b.start));return html.slice(0,cut)+`<section class="section agenda-list"><div class="section-title"><h2>${agendaView==='day'?'Compromissos de '+fmt(chosen):agendaView==='done'?'Compromissos concluídos':'Próximos compromissos'}</h2><label class="compact-label">Exibir<select id="agenda-view"><option value="upcoming" ${agendaView==='upcoming'?'selected':''}>Próximos compromissos</option><option value="day" ${agendaView==='day'?'selected':''}>Dia selecionado · ${fmt(chosen)}</option><option value="done" ${agendaView==='done'?'selected':''}>Concluídos</option></select></label></div><div class="schedule-list">${es.map(eventRow).join('')||empty('Nenhum compromisso nesta seleção','Escolha um dia no calendário ou crie um compromisso.','new:event','Novo compromisso')}</div></section>`};
const layoutAction=action;action=async function(a){if(a.startsWith('day:')||a==='today')agendaView='day';return layoutAction(a)};
workCard=function(p){const done=p.checks.filter(c=>c.done).length,total=p.checks.length;return `<article class="card job-card tidy-job" style="--stage-color:${stageColors[p.stage]||'#677570'}">${p.cover?`<img class="project-cover-small" src="${esc(p.cover)}" alt="Capa do trabalho">`:''}<div class="between"><small>${esc(p.type)}</small><span class="soft-chip project-stage">${esc(p.stage)}</span></div><h3>${esc(p.name)}</h3><p class="muted">${esc(client(p.clientId)?.name)}</p><div class="job-dates"><span>Data da sessão<b>${fmt(p.date)}</b></span><span>Prazo de entrega<b>${fmt(p.due)}</b></span></div>${p.due&&p.due<today()&&active(p)?'<p class="deadline-note">Prazo geral vencido · confira as entregas</p>':''}<div class="job-progress"><span>${done} de ${total} tarefas concluídas</span><progress max="${total||1}" value="${done}" aria-label="Tarefas concluídas"></progress></div><div class="item-controls">${btn('Abrir trabalho','project:'+p.id,'arrow','primary')}${compactActions(btn('Editar','edit:project:'+p.id,'edit')+btn('Excluir','delete-job:'+p.id,'trash','danger'))}</div></article>`};
projectsPage=function(){const ps=state.projects.filter(p=>(!filter||p.type===filter)&&(!stageFilter||p.stage===stageFilter)&&(p.name+' '+(client(p.clientId)?.name||'')).toLowerCase().includes(query.toLowerCase()));return header('Trabalhos','Acompanhe cada produção, da preparação à entrega.',btn('Novo trabalho','new:project','plus','primary'))+`<div class="project-filters"><label class="search-label">Buscar trabalho ou cliente<input id="search" value="${esc(query)}" placeholder="Digite um nome" type="search"></label><label>Etapa<select id="project-stage-filter"><option value="">Todas as etapas</option>${stages.map(s=>`<option value="${esc(s)}" ${stageFilter===s?'selected':''}>${esc(s)} (${state.projects.filter(p=>p.stage===s).length})</option>`).join('')}</select></label><label>Serviço<select id="filter"><option value="">Foto e vídeo</option>${['Fotografia','Vídeo','Foto + Vídeo'].map(t=>`<option ${filter===t?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="results-count">${ps.length} trabalho(s) nesta seleção</p><div class="grid cols3" id="results">${ps.map(workCard).join('')||empty('Nenhum trabalho encontrado','Altere os filtros ou crie um trabalho.','new:project','Novo trabalho')}</div>`};
morePage=function(){return header('Mais opções','Acesse as outras áreas do estúdio.')+`<div class="more-grid uniform-more">${[['quotes','Propostas e contratos','Criar, editar e gerar PDF em A4','file'],['finance','Financeiro','Recebimentos, despesas e saldo','wallet'],['gear','Equipamentos','Cadastro e situação do seu kit','camera'],['partners','Fornecedores e parceiros','Contatos, equipe e custos por trabalho','users'],['settings','Configurações','Perfil, senha e backup','settings']].map(([r,t,d,i])=>`<button class="card more-card" data-action="nav:${r}">${icon(i)}<span class="grow"><b>${t}</b><small class="block">${d}</small></span>${icon('arrow')}</button>`).join('')}</div>`};
const layoutMetric=metric;metric=function(label,...args){const tone={'Recebido líquido':'income','Despesas pagas':'expense','Saldo de caixa':'cash','Saldo a receber':'forecast','Falta receber':'forecast'}[label];return layoutMetric(label,...args).replace('card metric','card metric'+(tone?' financial-metric tone-'+tone:''))};
financeRows=function(pid){return state.transactions.filter(t=>!pid||t.projectId===pid).sort((a,b)=>b.date.localeCompare(a.date)).map(t=>{const tone=t.type==='Recebimento'?'income':t.type==='Despesa'?'expense':'forecast';return `<article class="ledger-item tone-${tone}"><div class="ledger-heading"><span class="soft-chip tone-${tone}">${esc(t.type==='Recebimento'?'Recebido':t.type==='Despesa'?'Despesa paga':t.type)}</span><time>${fmt(t.date)}</time></div><h3>${esc(t.description)}</h3><p class="muted">${esc(project(t.projectId)?.name||'Sem trabalho vinculado')}</p><strong class="ledger-amount">${t.type==='Recebimento'?'+':'−'} ${money(t.amount)}</strong><div class="item-controls">${btn('Editar','transaction:'+t.id,'edit')}${compactActions(btn('Excluir','delete:transaction:'+t.id,'trash','danger'))}</div></article>`}).join('')||empty('Nenhum lançamento','Registre recebimentos e despesas efetivados.')};
document.addEventListener('change',e=>{if(e.target.id==='project-stage-filter'){stageFilter=e.target.value;render()}if(e.target.id==='agenda-view'){agendaView=e.target.value;render()}});

/* V0.6.0 — intervalos da agenda */
let agendaPeriod='month',agendaStatus='all';
const periodLabels={day:'Dia',week:'Semana',fortnight:'Quinzenal',month:'Mensal',quarter:'Trimestral'};
function calendarShift(value,days){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+days);return localDate(d)}
function agendaBounds(value=chosen,kind=agendaPeriod){const d=new Date(value+'T12:00:00'),y=d.getFullYear(),m=d.getMonth();let start=value,end=value;if(kind==='week'){start=calendarShift(value,-d.getDay());end=calendarShift(start,6)}if(kind==='fortnight'){start=localDate(new Date(y,m,d.getDate()<=15?1:16));end=localDate(new Date(y,m,d.getDate()<=15?15:new Date(y,m+1,0).getDate()))}if(kind==='month'){start=localDate(new Date(y,m,1));end=localDate(new Date(y,m+1,0))}if(kind==='quarter'){const q=Math.floor(m/3)*3;start=localDate(new Date(y,q,1));end=localDate(new Date(y,q+3,0))}return {start,end}}
function periodEvents(start,end){return state.events.filter(e=>e.start.slice(0,10)<=end&&e.end.slice(0,10)>=start&&(agendaStatus==='all'||(agendaStatus==='done'?e.done:!e.done))).sort((a,b)=>a.start.localeCompare(b.start))}
function agendaDayButton(d,mini=false){const es=periodEvents(d,d);return `<button type="button" class="day ${d===today()?'today':''} ${d===chosen?'selected':''}" data-action="period-day:${d}" aria-label="${fmt(d)}, ${es.length} compromissos"><span>${Number(d.slice(8))}</span>${es.length?`<small>${mini?es.length:es.length+' compromisso'+(es.length>1?'s':'')}</small>`:''}</button>`}
function agendaMonthGrid(value,mini=false){const [y,m]=value.split('-').map(Number),first=new Date(y,m-1,1).getDay(),days=new Date(y,m,0).getDate();return `<div class="calendar ${mini?'mini-calendar':''}">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(x=>`<div class="weekday">${x}</div>`).join('')}${'<div class="day off"></div>'.repeat(first)}${Array.from({length:days},(_,i)=>agendaDayButton(`${value}-${String(i+1).padStart(2,'0')}`,mini)).join('')}</div>`}
agendaPage=function(){const {start,end}=agendaBounds(),es=periodEvents(start,end);let calendar='';if(agendaPeriod==='month')calendar=agendaMonthGrid(start.slice(0,7));else if(agendaPeriod==='quarter'){const d=new Date(start+'T12:00:00');calendar='<div class="quarter-calendars">'+Array.from({length:3},(_,i)=>{const date=new Date(d.getFullYear(),d.getMonth()+i,1);return `<section><h3>${date.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h3>${agendaMonthGrid(localDate(date).slice(0,7),true)}</section>`}).join('')+'</div>'}else if(agendaPeriod==='day')calendar=`<div class="day-focus"><span>${new Date(chosen+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long'})}</span><strong>${fmt(chosen)}</strong><small>${es.length} compromisso(s)</small></div>`;else {let ds=[],d=start;while(d<=end){ds.push(d);d=calendarShift(d,1)}calendar=`<div class="period-days">${ds.map(d=>`<div><span>${new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'})}</span>${agendaDayButton(d,true)}</div>`).join('')}</div>`}
return header('Agenda','Organize sessões, reuniões e lembretes.',btn('Novo compromisso','new:event','plus','primary'))+`<section class="card agenda-period-card"><div class="period-switch" role="group" aria-label="Período da agenda">${Object.entries(periodLabels).map(([k,l])=>`<button type="button" data-action="period:${k}" aria-pressed="${agendaPeriod===k}" class="${agendaPeriod===k?'selected':''}">${l}</button>`).join('')}</div><div class="period-navigation"><button class="icon-btn" data-action="period-step:-1" aria-label="Período anterior">${icon('back')}</button><h2>${start===end?fmt(start):fmt(start)+' — '+fmt(end)}</h2><button class="icon-btn" data-action="period-step:1" aria-label="Próximo período">${icon('arrow')}</button></div><div class="period-tools"><label>Ir para a data<input type="date" id="agenda-date" value="${chosen}"></label>${btn('Hoje','period-today')}</div>${calendar}<p class="legend">${agendaPeriod==='fortnight'?'Quinzenas: dias 1 a 15 e 16 ao fim do mês.':agendaPeriod==='quarter'?'Trimestres: jan–mar, abr–jun, jul–set e out–dez.':agendaPeriod==='week'?'Semana de domingo a sábado.':''} ${agendaPeriod!=='day'?'Toque em um dia para ver seus horários.':''}</p></section><section class="section agenda-list"><div class="section-title"><div><h2>Compromissos do período</h2><p class="muted">${es.length} compromisso(s) · ${start===end?fmt(start):fmt(start)+' a '+fmt(end)}</p></div><label class="compact-label">Situação<select id="agenda-status"><option value="all" ${agendaStatus==='all'?'selected':''}>Todos</option><option value="pending" ${agendaStatus==='pending'?'selected':''}>Pendentes</option><option value="done" ${agendaStatus==='done'?'selected':''}>Concluídos</option></select></label></div><div class="schedule-list">${es.map(eventRow).join('')||empty('Nenhum compromisso neste período','Altere a data, a situação ou crie um compromisso.','new:event','Novo compromisso')}</div></section>`};
const periodAction=action;action=async function(a){const [cmd,v]=a.split(':');if(cmd==='period'){if(!periodLabels[v])return;agendaPeriod=v;render();return}if(cmd==='period-day'){chosen=v;month=v.slice(0,7);agendaPeriod='day';render();return}if(cmd==='period-today'){chosen=today();month=chosen.slice(0,7);render();return}if(cmd==='period-step'){const {start,end}=agendaBounds();chosen=calendarShift(Number(v)>0?end:start,Number(v)>0?1:-1);month=chosen.slice(0,7);render();return}return periodAction(a)};
document.addEventListener('change',e=>{if(e.target.id==='agenda-date'&&/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)){chosen=e.target.value;month=chosen.slice(0,7);render()}if(e.target.id==='agenda-status'){agendaStatus=e.target.value;render()}});



