/* V0.6.1 — agenda limpa, tela Inicial e financeiro gerencial */
const v61HomePage=homePage;
homePage=function(){
  return v61HomePage().replace(/<p class="home-guide">[\s\S]*?<\/p>\s*$/,'');
};

function financeDefaults(){return {accounts:['Conta principal','Dinheiro'],incomeCategories:['Sinal','Parcela do cliente','Ensaio','Evento','Álbum','Outras receitas'],expenseCategories:['Equipe e parceiros','Transporte','Locação','Impressão e álbum','Manutenção','Marketing','Software','Impostos','Outras despesas']}}
function financeConfig(){const d=financeDefaults(),c=state.financeConfig||{};return {accounts:Array.isArray(c.accounts)&&c.accounts.length?c.accounts:d.accounts,incomeCategories:Array.isArray(c.incomeCategories)&&c.incomeCategories.length?c.incomeCategories:d.incomeCategories,expenseCategories:Array.isArray(c.expenseCategories)&&c.expenseCategories.length?c.expenseCategories:d.expenseCategories}}
const v61Validate=validate;
validate=function(d){
  d.financeConfig??=financeDefaults();
  const c=d.financeConfig;
  for(const k of ['accounts','incomeCategories','expenseCategories'])if(!Array.isArray(c[k])||!c[k].length||c[k].length>100||c[k].some(x=>typeof x!=='string'||!x.trim()||x.length>80))throw Error('Configuração financeira inválida.');
  for(const t of d.transactions){for(const k of ['category','account','paymentMethod','competence','document','notes'])if(t[k]!=null&&typeof t[k]!=='string')throw Error('Detalhe financeiro inválido.');if(t.competence&&!/^\d{4}-\d{2}$/.test(t.competence))throw Error('Competência financeira inválida.');}
  return v61Validate(d);
};

function financeTransactionForm(id=null,pid=''){
  const x=state.transactions.find(t=>t.id===id)||{},c=financeConfig(),income=x.type!=='Despesa';
  const projectOptions=[['','Sem trabalho vinculado'],...state.projects.map(p=>[p.id,p.name])];
  modal(id?'Editar lançamento':'Novo lançamento',`<input type="hidden" name="id" value="${esc(id||'')}"><div class="grid cols2 form-cols">
    ${select('Trabalho ou projeto','projectId',projectOptions,x.projectId||pid||'')}
    ${select('Movimento','type',['Recebimento','Despesa','Estorno'],x.type||'Recebimento','required')}
    ${field('Descrição','description',x.description||'','text','required maxlength="160"')}
    <label>Valor (R$)<input name="amount" value="${x.amount?(x.amount/100).toFixed(2).replace('.',','):''}" inputmode="decimal" placeholder="0,00" required></label>
    ${field('Data efetiva','date',x.date||today(),'date','required')}
    ${field('Competência','competence',x.competence||(x.date||today()).slice(0,7),'month','required')}
    ${select('Categoria','category',[...new Set([...c.incomeCategories,...c.expenseCategories])],x.category||(income?c.incomeCategories[0]:c.expenseCategories[0]),'required')}
    ${select('Conta / caixa','account',c.accounts,x.account||c.accounts[0],'required')}
    ${select('Forma de pagamento','paymentMethod',['Pix','Dinheiro','Cartão','Transferência','Boleto','Outro'],x.paymentMethod||'Pix')}
    ${field('Documento ou referência','document',x.document||'','text','maxlength="80"')}
    ${area('Observações','notes',x.notes||'','maxlength="800"')}
  </div><p class="legend">Use esta tela para valores já recebidos ou pagos. Valores futuros devem ser planejados em Contas a receber ou Contas a pagar.</p>`,'finance-transaction',id?'Salvar alterações':'Salvar lançamento');
}
const v61OpenForm=openForm;
openForm=function(kind,id=null,pid=null){if(kind==='transaction')return financeTransactionForm(id,pid||'');return v61OpenForm(kind,id,pid)};

function financeSetupForm(){const c=financeConfig();modal('Contas e categorias',`<p class="notice">Informe um item por linha. Itens já usados permanecem nos lançamentos antigos.</p>${area('Contas e caixas','accounts',c.accounts.join('\n'),'required')}${area('Categorias de receitas','incomeCategories',c.incomeCategories.join('\n'),'required')}${area('Categorias de despesas','expenseCategories',c.expenseCategories.join('\n'),'required')}`,'finance-setup','Salvar listas')}
function cleanLines(v){return [...new Set(String(v||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean))].slice(0,100)}
const v61Submit=submit;
submit=async function(kind,f){
  if(kind==='finance-setup'){const v=Object.fromEntries(new FormData(f)),next={accounts:cleanLines(v.accounts),incomeCategories:cleanLines(v.incomeCategories),expenseCategories:cleanLines(v.expenseCategories)};if(Object.values(next).some(a=>!a.length))throw Error('Mantenha ao menos uma conta e uma categoria de cada tipo.');await commit(d=>d.financeConfig=next,'Listas financeiras atualizadas');closeModal(true);toast('Contas e categorias atualizadas.');return}
  if(kind==='finance-transaction'){const v=Object.fromEntries(new FormData(f)),amount=parseMoney(v.amount);if(amount<=0)throw Error('O valor deve ser maior que zero.');if(!v.description.trim())throw Error('Informe a descrição.');if(v.type==='Estorno'&&!v.projectId)throw Error('Vincule o estorno ao trabalho que recebeu o valor.');if(v.type==='Estorno'){const available=state.transactions.filter(x=>x.projectId===v.projectId&&x.id!==v.id).reduce((s,x)=>s+(x.type==='Recebimento'?x.amount:x.type==='Estorno'?-x.amount:0),0);if(amount>available)throw Error('O estorno não pode superar o recebido líquido deste trabalho.')}const t={id:v.id||uid(),projectId:v.projectId||'',type:v.type,description:v.description.trim(),amount,date:v.date,competence:v.competence,category:v.category,account:v.account,paymentMethod:v.paymentMethod,document:v.document.trim(),notes:v.notes.trim(),reconciled:state.transactions.find(x=>x.id===v.id)?.reconciled||false};await commit(d=>{const i=d.transactions.findIndex(x=>x.id===t.id);i<0?d.transactions.push(t):d.transactions.splice(i,1,t)},'Lançamento financeiro salvo');closeModal(true);toast('Lançamento salvo e totais atualizados.');return}
  return v61Submit(kind,f);
};

let financeTab61='overview',financeFrom61='',financeTo61='',financeType61='all',financeQuery61='',financeMoneyVisible=true;
function cashDelta(t){return t.type==='Recebimento'?t.amount:-t.amount}
function financeFiltered(){return state.transactions.filter(t=>(!financeFrom61||t.date>=financeFrom61)&&(!financeTo61||t.date<=financeTo61)&&(financeType61==='all'||t.type===financeType61)&&(!financeQuery61||(t.description+' '+(t.category||'')+' '+(project(t.projectId)?.name||'')).toLowerCase().includes(financeQuery61.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date))}
function pendingFinance(kind){
  const installments=(state.installments||[]).filter(s=>!s.transactionId&&(kind==='pay'?!!s.assignmentId:!s.assignmentId)).map(s=>({...s,source:'Parcela'}));
  if(kind==='pay')for(const a of state.assignments||[])if(!a.transactionId&&!(state.installments||[]).some(s=>s.assignmentId===a.id))installments.push({id:a.id,projectId:a.projectId,assignmentId:a.id,description:a.service,amount:a.amount,due:a.due||'',source:'Parceiro'});
  return installments.sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));
}
function financialMetrics61(){const all=state.transactions,received=all.reduce((n,t)=>n+(t.type==='Recebimento'?t.amount:t.type==='Estorno'?-t.amount:0),0),paid=all.filter(t=>t.type==='Despesa').reduce((n,t)=>n+t.amount,0),receivable=state.projects.filter(active).reduce((n,p)=>n+Math.max(0,p.value-totals(p.id).paid),0),payable=pendingFinance('pay').reduce((n,x)=>n+x.amount,0),overdue=[...pendingFinance('receive'),...pendingFinance('pay')].filter(x=>x.due&&x.due<today()).reduce((n,x)=>n+x.amount,0);return {received,paid,cash:received-paid,receivable,payable,overdue}}
function moneyText(v){return financeMoneyVisible?money(v):'R$ •••••'}
function financeMetric61(label,value,detail,tone){return `<article class="card finance-kpi tone-${tone}"><span>${esc(label)}</span><strong>${moneyText(value)}</strong><small>${esc(detail)}</small></article>`}
function financeLedger61(list=financeFiltered()){
  return `<div class="finance-ledger">${list.map(t=>{const tone=t.type==='Recebimento'?'income':t.type==='Despesa'?'expense':'forecast';return `<article class="ledger-item tone-${tone}"><div class="ledger-heading"><span class="soft-chip tone-${tone}">${t.type==='Recebimento'?'Receita recebida':t.type==='Despesa'?'Despesa paga':'Estorno'}</span><time>${fmt(t.date)}</time></div><div class="ledger-main"><div><h3>${esc(t.description)}</h3><p>${esc(t.category||'Sem categoria')} · ${esc(t.account||'Conta principal')}${project(t.projectId)?' · '+esc(project(t.projectId).name):''}</p></div><strong class="ledger-amount">${t.type==='Recebimento'?'+':'−'} ${moneyText(t.amount)}</strong></div><div class="ledger-foot"><small>${esc(t.paymentMethod||'Forma não informada')}${t.competence?' · competência '+t.competence.split('-').reverse().join('/'):''}</small><span class="soft-chip ${t.reconciled?'tone-income':'tone-forecast'}">${t.reconciled?'Conferido':'A conferir'}</span></div><div class="item-controls">${btn('Editar','transaction:'+t.id,'edit')}${btn(t.reconciled?'Desmarcar conferência':'Marcar como conferido','finance-reconcile:'+t.id,'check')}${compactActions(btn('Excluir','delete:transaction:'+t.id,'trash','danger'))}</div></article>`}).join('')||empty('Nenhuma movimentação encontrada','Altere os filtros ou registre um novo lançamento.','new:transaction','Novo lançamento')}</div>`
}
function dueRows61(kind){const list=pendingFinance(kind),isPay=kind==='pay';return `<div class="finance-ledger">${list.map(s=>{const p=project(s.projectId),a=(state.assignments||[]).find(x=>x.id===s.assignmentId),party=isPay?(state.partners||[]).find(x=>x.id===a?.partnerId):client(p?.clientId),late=s.due&&s.due<today();return `<article class="due-card ${late?'late':''}"><div class="between"><span class="soft-chip ${isPay?'tone-expense':'tone-income'}">${late?'Vencido':isPay?'A pagar':'A receber'}</span><strong>${moneyText(s.amount)}</strong></div><h3>${esc(s.description)}</h3><p>${esc(p?.name||'Sem trabalho')} · ${esc(party?.name||'Contato não informado')}</p><div class="due-date"><span>Vencimento</span><b>${s.due?fmt(s.due):'Sem data'}</b></div><div class="item-controls">${s.source==='Parcela'?btn(isPay?'Registrar pagamento':'Registrar recebimento','settle-installment:'+s.id,'wallet','primary'):btn('Abrir custos do trabalho','team:'+s.projectId,'users','primary')}${s.source==='Parcela'?compactActions(btn('Editar','edit-installment:'+s.id,'edit')+btn('Excluir','delete-installment:'+s.id,'trash','danger')):''}</div></article>`}).join('')||empty(isPay?'Nenhuma conta a pagar':'Nenhuma conta a receber',isPay?'Os custos planejados de parceiros aparecerão aqui.':'Planeje parcelas dentro de cada trabalho.')}</div>`}
function monthKeyShift(n){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function cashFlow61(){const months=Array.from({length:6},(_,i)=>monthKeyShift(i-5)),values=months.map(m=>{const ts=state.transactions.filter(t=>(t.competence||t.date.slice(0,7))===m);return {m,income:ts.filter(t=>t.type==='Recebimento').reduce((n,t)=>n+t.amount,0),expense:ts.filter(t=>t.type!=='Recebimento').reduce((n,t)=>n+t.amount,0)}}),max=Math.max(1,...values.flatMap(x=>[x.income,x.expense]));return `<div class="cash-chart" aria-label="Fluxo de caixa dos últimos seis meses">${values.map(x=>`<div class="cash-month"><div class="cash-bars"><i class="income" style="height:${Math.max(3,x.income/max*100)}%" title="Entradas ${money(x.income)}"></i><i class="expense" style="height:${Math.max(3,x.expense/max*100)}%" title="Saídas ${money(x.expense)}"></i></div><span>${new Date(x.m+'-02T12:00:00').toLocaleDateString('pt-BR',{month:'short'})}</span></div>`).join('')}</div>`}
function projectFinance61(){return `<div class="project-finance-grid">${state.projects.filter(active).map(p=>{const t=totals(p.id),profit=t.paid-t.cost,margin=t.paid?Math.round(profit/t.paid*100):0;return `<article class="card project-finance-card"><div class="between"><div><small>${esc(client(p.clientId)?.name)}</small><h3>${esc(p.name)}</h3></div><span class="soft-chip project-stage" style="--stage-color:${stageColors[p.stage]||'#677570'}">${esc(p.stage)}</span></div><dl><div><dt>Contratado</dt><dd>${moneyText(p.value)}</dd></div><div><dt>Recebido</dt><dd>${moneyText(t.paid)}</dd></div><div><dt>Despesas</dt><dd>${moneyText(t.cost)}</dd></div><div><dt>Resultado realizado</dt><dd class="${profit>=0?'positive':'negative'}">${moneyText(profit)}</dd></div></dl><div class="margin-line"><span>Margem realizada</span><b>${margin}%</b></div>${btn('Abrir trabalho','project:'+p.id,'arrow')}</article>`}).join('')||empty('Nenhum trabalho ativo','Crie um trabalho para acompanhar receita, custo e margem.')}</div>`}
function accountsAndCategories61(){const c=financeConfig();return `<div class="grid cols2"><section class="card"><div class="between section-title"><h2>Caixa e contas</h2>${btn('Configurar','finance-setup','settings')}</div>${c.accounts.map(name=>{const balance=state.transactions.filter(t=>(t.account||c.accounts[0])===name).reduce((n,t)=>n+cashDelta(t),0);return `<div class="account-row"><span>${esc(name)}</span><b>${moneyText(balance)}</b></div>`}).join('')}</section><section class="card"><h2>Categorias utilizadas</h2>${[...new Set(state.transactions.map(t=>t.category||'Sem categoria'))].map(name=>{const total=state.transactions.filter(t=>(t.category||'Sem categoria')===name).reduce((n,t)=>n+Math.abs(cashDelta(t)),0);return `<div class="account-row"><span>${esc(name)}</span><b>${moneyText(total)}</b></div>`}).join('')||'<p class="muted">As categorias aparecerão conforme os lançamentos.</p>'}</section></div>`}
function financeOverview61(){const m=financialMetrics61(),latest=state.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<div class="finance-kpis">${financeMetric61('Receitas recebidas',m.received,'Entradas líquidas de estornos','income')}${financeMetric61('Despesas pagas',m.paid,'Saídas efetivadas','expense')}${financeMetric61('Saldo realizado',m.cash,'Entradas menos saídas','cash')}${financeMetric61('Saldo contratado',m.receivable,'Ainda falta receber dos trabalhos','forecast')}${financeMetric61('Contas a pagar',m.payable,'Custos planejados','expense')}${financeMetric61('Valores vencidos',m.overdue,'Recebimentos e pagamentos atrasados','forecast')}</div><div class="grid cols2 section"><section class="card"><div class="between section-title"><div><h2>Fluxo dos últimos 6 meses</h2><p class="muted">Entradas e saídas por competência</p></div><span class="chart-legend"><i></i> Entradas <i></i> Saídas</span></div>${cashFlow61()}</section><section class="card"><div class="between section-title"><div><h2>Próximos vencimentos</h2><p class="muted">O que exige atenção primeiro</p></div><button class="link-btn" data-action="finance-tab:receive">Ver contas</button></div>${[...pendingFinance('receive').map(x=>({...x,k:'Receber'})),...pendingFinance('pay').map(x=>({...x,k:'Pagar'}))].sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4).map(x=>`<div class="overview-due"><span class="soft-chip ${x.k==='Receber'?'tone-income':'tone-expense'}">${x.k}</span><div class="grow"><b>${esc(x.description)}</b><small>${x.due?fmt(x.due):'Sem vencimento'}</small></div><strong>${moneyText(x.amount)}</strong></div>`).join('')||'<p class="muted">Nenhum vencimento planejado.</p>'}</section></div><section class="card section"><div class="between section-title"><h2>Últimas movimentações</h2><button class="link-btn" data-action="finance-tab:movements">Ver todas</button></div>${financeLedger61(latest)}</section>`}
function financePage(){const tabs=[['overview','Visão geral'],['movements','Movimentações'],['receive','A receber'],['pay','A pagar'],['projects','Por trabalho'],['accounts','Contas e categorias']];let content=financeTab61==='overview'?financeOverview61():financeTab61==='movements'?`<section class="card finance-filters"><div class="grid cols4"><label>De<input id="finance-from" type="date" value="${financeFrom61}"></label><label>Até<input id="finance-to" type="date" value="${financeTo61}"></label><label>Tipo<select id="finance-type"><option value="all">Todos</option>${['Recebimento','Despesa','Estorno'].map(x=>`<option ${financeType61===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Buscar<input id="finance-search" type="search" value="${esc(financeQuery61)}" placeholder="Descrição, categoria ou trabalho"></label></div></section>${financeLedger61()}`:financeTab61==='receive'?dueRows61('receive'):financeTab61==='pay'?dueRows61('pay'):financeTab61==='projects'?projectFinance61():accountsAndCategories61();return header('Financeiro','Caixa, vencimentos, custos e resultado de cada trabalho.',btn('Novo lançamento','new:transaction','plus','primary'))+`<div class="finance-toolbar"><div><span class="eyebrow">PAINEL FINANCEIRO</span><h2>Decisões com números claros.</h2></div><div class="row wrap">${btn(financeMoneyVisible?'Ocultar valores':'Mostrar valores','finance-toggle-money','eye')}${btn('Exportar CSV','finance-csv','download')}</div></div><nav class="finance-tabs" aria-label="Áreas do financeiro">${tabs.map(([k,l])=>`<button class="${financeTab61===k?'active':''}" data-action="finance-tab:${k}">${l}</button>`).join('')}</nav>${content}`}

/* A agenda mostra primeiro o período e, logo abaixo, os compromissos correspondentes. */
agendaPage=function(){const {start,end}=agendaBounds(),es=periodEvents(start,end);let calendar='';if(agendaPeriod==='month')calendar=agendaMonthGrid(start.slice(0,7));else if(agendaPeriod==='quarter'){const d=new Date(start+'T12:00:00');calendar='<div class="quarter-calendars">'+Array.from({length:3},(_,i)=>{const date=new Date(d.getFullYear(),d.getMonth()+i,1);return `<section><h3>${date.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h3>${agendaMonthGrid(localDate(date).slice(0,7),true)}</section>`}).join('')+'</div>'}else if(agendaPeriod==='day')calendar=`<div class="day-focus"><span>${new Date(chosen+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long'})}</span><strong>${fmt(chosen)}</strong><small>${es.length} compromisso(s)</small></div>`;else{let ds=[],d=start;while(d<=end){ds.push(d);d=calendarShift(d,1)}calendar=`<div class="period-days">${ds.map(d=>`<div><span>${new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'})}</span>${agendaDayButton(d,true)}</div>`).join('')}</div>`}const range=start===end?fmt(start):fmt(start)+' a '+fmt(end);return header('Agenda','Sessões, reuniões, entregas e lembretes em uma única linha do tempo.',btn('Novo compromisso','new:event','plus','primary'))+`<section class="card agenda-command"><div class="agenda-view-head"><div><span class="eyebrow">VISUALIZAÇÃO</span><h2>Como deseja consultar?</h2></div><label class="agenda-jump">Ir para<input type="date" id="agenda-date" value="${chosen}"></label></div><div class="period-switch" role="group" aria-label="Período da agenda">${Object.entries(periodLabels).map(([k,l])=>`<button type="button" data-action="period:${k}" aria-pressed="${agendaPeriod===k}" class="${agendaPeriod===k?'selected':''}">${l}</button>`).join('')}</div><div class="period-navigation"><button class="icon-btn" data-action="period-step:-1" aria-label="Período anterior">${icon('back')}</button><div><small>PERÍODO EXIBIDO</small><h2>${range}</h2></div><button class="icon-btn" data-action="period-step:1" aria-label="Próximo período">${icon('arrow')}</button></div><div class="agenda-today-row">${btn('Ir para hoje','period-today','calendar')}<span>${es.length} compromisso(s) neste período</span></div><div class="agenda-calendar-wrap">${calendar}</div></section><section class="section agenda-list"><div class="agenda-list-head"><div><span class="eyebrow">AGENDA DO PERÍODO</span><h2>Próximos compromissos</h2><p>Compromissos do período · ${range}</p></div><label>Situação<select id="agenda-status"><option value="all" ${agendaStatus==='all'?'selected':''}>Todos</option><option value="pending" ${agendaStatus==='pending'?'selected':''}>Pendentes</option><option value="done" ${agendaStatus==='done'?'selected':''}>Concluídos</option></select></label></div><div class="schedule-list">${es.map(eventRow).join('')||empty('Período livre','Mude a data ou adicione um compromisso.','new:event','Novo compromisso')}</div></section>`};

const v61Action=action;
action=async function(a){const [cmd,id]=a.split(':');if(cmd==='finance-tab'){financeTab61=id;render();return}if(cmd==='finance-toggle-money'){financeMoneyVisible=!financeMoneyVisible;render();return}if(cmd==='finance-setup')return financeSetupForm();if(cmd==='finance-reconcile'){await commit(d=>{const t=d.transactions.find(x=>x.id===id);if(t)t.reconciled=!t.reconciled},'Conferência financeira atualizada');return}if(cmd==='finance-csv'){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"',rows=[['Data','Competência','Tipo','Descrição','Categoria','Conta','Pagamento','Trabalho','Valor R$','Conferido'],...state.transactions.map(t=>[t.date,t.competence||t.date.slice(0,7),t.type,t.description,t.category||'',t.account||'',t.paymentMethod||'',project(t.projectId)?.name||'',(t.amount/100).toFixed(2).replace('.',','),t.reconciled?'Sim':'Não'])];download('LensCore-financeiro-'+today()+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Relatório financeiro exportado.');return}return v61Action(a)};
document.addEventListener('change',e=>{if(e.target.id==='finance-from'){financeFrom61=e.target.value;render()}if(e.target.id==='finance-to'){financeTo61=e.target.value;render()}if(e.target.id==='finance-type'){financeType61=e.target.value;render()}if(e.target.id==='finance-search'){financeQuery61=e.target.value;render()}});
